"use strict";
/* 健康保険法 追加問題(X5/XT5/XS5)。ID恒久。法令基準日2026-04-01(令和8年度試験想定)。 */
(window.QPARTS = window.QPARTS || []).push(
 {id:"X5-001",s:5,q:"健康保険制度は、医療保険の運営の効率化、給付の内容及び費用の負担の適正化並びに国民が受ける医療の質の向上を総合的に図りつつ実施されなければならない旨が法定されている。",a:true,e:"基本理念(2条)の内容どおり。高齢化・疾病構造の変化等に対応し、在り方に常に検討を加えるとも規定。",topic:"基本理念"},
 {id:"X5-002",s:5,q:"健康保険の保険者は、全国健康保険協会、健康保険組合及び市町村である。",a:false,e:"保険者は全国健康保険協会と健康保険組合の2つだけ(4条)。市町村は国民健康保険の保険者で、健保の保険者ではない。",topic:"保険者"},
 {id:"X5-003",s:5,q:"全国健康保険協会は、健康保険組合の組合員でない被保険者の保険を管掌する。",a:true,e:"5条1項のとおり。組合員でない被保険者(協会けんぽ)を協会が管掌する。日雇特例被保険者の保険も協会が管掌(123条)。",topic:"保険者"},
 {id:"X5-004",s:5,q:"日雇特例被保険者の保険の保険者は、全国健康保険協会のほか、規約で定めた健康保険組合もなることができる。",a:false,e:"日雇特例被保険者の保険の保険者は協会のみ(123条1項)。健康保険組合が日雇特例被保険者の保険を管掌することはない。",topic:"保険者"},
 {id:"X5-005",s:5,q:"健康保険組合の組合員であった者が任意継続被保険者となったときは、その者の保険は全国健康保険協会が管掌する。",a:false,e:"任意継続被保険者は資格喪失時の保険者に加入する。組合員だった者はその健康保険組合の任意継続被保険者となる(5条1項・3条4項)。",topic:"保険者"},
 {id:"X5-006",s:5,q:"全国健康保険協会の理事長及び監事は厚生労働大臣が任命し、理事は理事長が任命する。",a:true,e:"7条の11のとおり。役員は理事長1人・理事6人以内・監事2人(7条の9)。理事長は理事を任命したときは遅滞なく大臣に届け出て公表する。",topic:"全国健康保険協会"},
 {id:"X5-007",s:5,q:"全国健康保険協会の理事は、運営委員会の議を経て厚生労働大臣が任命する。",a:false,e:"大臣が任命するのは理事長と監事。理事は理事長が任命する(7条の11第2項)。理事を大臣任命としたのが誤り。",topic:"全国健康保険協会"},
 {id:"X5-008",s:5,q:"全国健康保険協会に置かれる運営委員会の委員は15人以内とし、事業主及び被保険者のうちから理事長が任命する。",a:false,e:"委員は9人以内で、事業主・被保険者・学識経験者から各同数を厚生労働大臣が任命する(7条の18)。15人・理事長任命が誤り。",topic:"全国健康保険協会"},
 {id:"X5-009",s:5,q:"全国健康保険協会の都道府県ごとの支部には、評議会が設けられ、支部の業務の実施について評議を行う。",a:true,e:"7条の21のとおり。評議員は支部長が委嘱。支部長は都道府県単位保険料率の変更にあたり評議会の意見を聴く(160条)。",topic:"全国健康保険協会"},
 {id:"X5-010",s:5,q:"全国健康保険協会は、毎事業年度、事業計画及び予算を作成し、当該事業年度開始前に、厚生労働大臣の認可を受けなければならない。",a:true,e:"7条の27のとおり。変更するときも同様に大臣の認可が必要。財務諸表は事業年度終了後に大臣の承認を受ける。",topic:"全国健康保険協会"},
 {id:"X5-011",s:5,q:"全国健康保険協会の一般保険料率は、支部被保険者を単位として、1000分の30から1000分の130までの範囲内で協会が決定する。",a:true,e:"都道府県単位保険料率(160条1項)。範囲は1000分の30〜130。健康保険組合の一般保険料率も同じ範囲(160条)。",topic:"保険料率"},
 {id:"X5-012",s:5,q:"全国健康保険協会が都道府県単位保険料率を変更するときは、理事長は運営委員会の議を経れば足り、厚生労働大臣への手続は不要である。",a:false,e:"理事長は運営委員会の議を経たうえで厚生労働大臣の認可を受けなければならない(160条)。支部長は事前に評議会の意見を聴く。",topic:"保険料率"},
 {id:"X5-013",s:5,q:"全国健康保険協会は、5年ごとに、翌事業年度以降10年間についての健康保険事業の収支の見通しを作成し、公表するものとされている。",a:false,e:"協会は2年ごとに、翌事業年度以降5年間の収支の見通しを作成・公表する(160条)。5年ごと・10年間が誤り。",topic:"全国健康保険協会"},
 {id:"X5-014",s:5,q:"2以上の事業主が共同して健康保険組合を設立するには、合算して常時1,000人以上の被保険者を使用していれば足りる。",a:false,e:"共同設立は合算して常時3,000人以上が必要(施行令)。単独設立は常時700人以上。1,000人は誤り。",topic:"健康保険組合"},
 {id:"X5-015",s:5,q:"健康保険組合の組合会の議員の定数は偶数とし、その半数は設立事業所の事業主が選定し、他の半数は被保険者である組合員が互選する。",a:true,e:"18条・施行令のとおり。事業主側と被保険者側が同数となる構成。理事も同じく半数ずつ。",topic:"健康保険組合"},
 {id:"X5-016",s:5,q:"健康保険組合の理事長は、被保険者である組合員が互選した理事のうちから、理事が選挙する。",a:false,e:"理事長は事業主が選定した組合会議員である理事のうちから、理事が選挙する(21条)。互選理事から選ぶとしたのが誤り。",topic:"健康保険組合"},
 {id:"X5-017",s:5,q:"健康保険組合は、組合会において組合会議員の定数の4分の3以上の多数により議決し、厚生労働大臣の認可を受けて解散することができる。",a:true,e:"26条1項・2項のとおり。事業の継続が不能となったとき、大臣の解散命令があったときも解散する。",topic:"健康保険組合"},
 {id:"X5-018",s:5,q:"健康保険組合が解散したときは、その権利義務は、厚生労働大臣が指定する他の健康保険組合が承継する。",a:false,e:"解散した健康保険組合の権利義務は全国健康保険協会が承継する(26条)。他の組合が承継するのではない。",topic:"健康保険組合"},
 {id:"X5-019",s:5,q:"健康保険組合は、規約を変更しようとするときは、原則として厚生労働大臣の認可を受けなければならないが、政令で定める軽微な事項は届出で足りる。",a:true,e:"16条2項・3項のとおり。事務所の所在地等の軽微な変更は遅滞なく届け出れば足りる。",topic:"健康保険組合"},
 {id:"X5-020",s:5,q:"厚生労働大臣は、財政状況等に照らし健全化を要する健康保険組合を指定することができ、指定を受けた組合は財政の健全化に関する計画を定め、大臣の承認を受けなければならない。",a:true,e:"指定健康保険組合(28条)。計画に従い事業を行わないときは、大臣が計画変更等を求めることができる。",topic:"健康保険組合"},
 {id:"X5-021",s:5,q:"全国健康保険協会は、定款で定めるところにより、法定の保険給付に併せて付加給付を行うことができる。",a:false,e:"付加給付は健康保険組合が規約で定めて行うもの(53条)。協会には付加給付の規定はない。",topic:"付加給付"},
 {id:"X5-022",s:5,q:"健康保険組合は、規約で定めるところにより、事業主の負担すべき一般保険料額又は介護保険料額の負担の割合を増加することができる。",a:true,e:"162条のとおり。原則は労使折半(161条1項)だが、組合は規約で事業主負担を増やせる。協会にはこの特例はない。",topic:"保険料の負担"},
 {id:"X5-023",s:5,q:"報酬を受けて常時法人の業務に従事する代表者1人だけの株式会社の事業所は、健康保険の強制適用事業所となる。",a:true,e:"法人の事業所で常時従業員を使用するものは業種を問わず強制適用(3条3項2号)。報酬を受ける法人代表者も使用される者として扱われる(通達)。",topic:"適用事業所"},
 {id:"X5-024",s:5,q:"常時5人以上の従業員を使用する個人経営の社会保険労務士事務所は、健康保険の強制適用事業所となる。",a:true,e:"令和4年10月から、弁護士・税理士・社労士等の法律・会計業務の士業が適用業種に追加された(3条3項1号)。",topic:"適用事業所"},
 {id:"X5-025",s:5,q:"常時10人の従業員を使用する個人経営の農業の事業所は、健康保険の強制適用事業所となる。",a:false,e:"個人経営の農林水産業は人数にかかわらず非適用業種で強制適用ではない(3条3項1号)。任意適用の認可(31条)で適用事業所になれる。",topic:"適用事業所"},
 {id:"X5-026",s:5,q:"常時8人の従業員を使用する個人経営の旅館は、健康保険の強制適用事業所となる。",a:false,e:"個人経営の宿泊業は非適用業種で強制適用ではない(3条3項1号)。法人経営であれば業種を問わず強制適用となる。",topic:"適用事業所"},
 {id:"X5-027",s:5,q:"常時4人の従業員を使用する個人経営の製造業の事業所は、健康保険の強制適用事業所となる。",a:false,e:"個人経営は適用業種であっても常時5人以上でなければ強制適用とならない(3条3項1号)。4人では任意適用のみ可能。",topic:"適用事業所"},
 {id:"X5-028",s:5,q:"国、地方公共団体又は法人の事業所であって、常時従業員を使用するものは、健康保険の適用事業所となる。",a:true,e:"3条3項2号のとおり。業種・人数を問わない。ただし共済組合の組合員には健保の保険給付・保険料の規定が適用されない(200条)。",topic:"適用事業所"},
 {id:"X5-029",s:5,q:"国家公務員共済組合の組合員である被保険者には、健康保険法による保険給付は行われず、保険料も徴収されない。",a:true,e:"200条のとおり。共済組合の組合員は共済組合から短期給付を受けるため、健保の保険給付・保険料の規定は適用しない。",topic:"適用事業所"},
 {id:"X5-030",s:5,q:"任意適用事業所の認可を受けたときは、その認可の申請に同意しなかった者も含め、当該事業所に使用される者は被保険者となる。",a:true,e:"31条の認可は事業所単位で効力を生じる。2分の1以上の同意で申請し、認可後は反対者も含め全員が被保険者となる(適用除外者を除く)。",topic:"任意適用"},
 {id:"X5-031",s:5,q:"強制適用事業所が従業員数の減少等により強制適用の要件に該当しなくなったときは、任意適用の認可があったものとみなされる。",a:true,e:"擬制的任意適用(32条)。自動的に適用除外とはならず、脱退するには取消しの認可(33条、4分の3以上の同意)が必要。",topic:"任意適用"},
 {id:"X5-032",s:5,q:"同一の事業主が2以上の適用事業所を有する場合は、事業主が届け出ることにより、当然にそれらを一の適用事業所とすることができる。",a:false,e:"一括適用は厚生労働大臣の承認を受けて行う(34条1項)。届出だけで一の適用事業所となるのではない。承認で他の事業所は適用事業所でなくなったものとみなされる。",topic:"一括適用"},
 {id:"X5-033",s:5,q:"日々雇い入れられる者は、2月を超えて引き続き使用されるに至ったときに、その超えた日から被保険者となる。",a:false,e:"日々雇い入れられる者は1月を超えて引き続き使用されるに至ったときに被保険者となる(3条1項2号イ)。2月は「2月以内の期間を定めて使用される者」の基準。",topic:"適用除外"},
 {id:"X5-034",s:5,q:"2月以内の期間を定めて使用される者が、所定の期間を超えて引き続き使用されるに至ったときは、その超えた日から被保険者となる。",a:true,e:"3条1項2号ロのとおり。当初から2月を超えて使用される見込みがある場合は当初から被保険者(令和4年10月改正)。",topic:"適用除外"},
 {id:"X5-035",s:5,q:"臨時的事業の事業所に使用される者は、継続して6月を超えて使用されるべき場合であっても、被保険者とならない。",a:false,e:"臨時的事業の事業所に使用される者は、継続して6月を超えて使用されるべき場合は当初から被保険者となる(3条1項5号)。",topic:"適用除外"},
 {id:"X5-036",s:5,q:"事業所で所在地が一定しないものに使用される者は、健康保険の一般の被保険者とならない。",a:true,e:"3条1項3号のとおり、巡回興行など所在地が一定しない事業所に使用される者は適用除外。要件を満たせば日雇特例被保険者となる。",topic:"適用除外"},
 {id:"X5-037",s:5,q:"船員保険の被保険者は、疾病任意継続被保険者を含め、健康保険の被保険者となることはない。",a:false,e:"適用除外は船員保険の被保険者のうち疾病任意継続被保険者を除く者(3条1項1号)。疾病任意継続被保険者は健保の被保険者となり得る。",topic:"適用除外"},
 {id:"X5-038",s:5,q:"国民健康保険組合の事業所に使用される者は、健康保険の被保険者とならない。",a:true,e:"3条1項6号のとおり。国保組合の事業所に使用される者は国保組合の被保険者となるため、健保では適用除外。",topic:"適用除外"},
 {id:"X5-039",s:5,q:"後期高齢者医療の被保険者は、適用事業所に使用される者であっても健康保険の被保険者とならない。",a:true,e:"3条1項7号のとおり。75歳に達すると後期高齢者医療の被保険者となり、その日に健保の資格を喪失する(36条)。",topic:"適用除外"},
 {id:"X5-040",s:5,q:"1週間の所定労働時間及び1月間の所定労働日数が、同一の事業所に使用される通常の労働者のいずれも4分の3以上である者は、短時間労働者の4要件を満たさなくても被保険者となる。",a:true,e:"いわゆる4分の3基準(3条1項9号)。これを満たせば一般の被保険者。満たさない場合に特定適用事業所等での4要件が問題となる。",topic:"短時間労働者"},
 {id:"X5-041",s:5,q:"特定適用事業所の短時間労働者が被保険者となるためには、継続して1年以上使用されることが見込まれることが必要である。",a:false,e:"1年以上の見込み要件は令和4年10月に撤廃。現在は通常の被保険者と同じく2月を超える見込みで判断する(3条1項9号)。",topic:"短時間労働者"},
 {id:"X5-042",s:5,q:"短時間労働者の適用に係る月額8.8万円以上の賃金要件の判定では、時間外労働の割増賃金、賞与及び通勤手当は算入しない。",a:true,e:"3条1項9号・施行規則の定め。臨時の賃金、1月超ごとの賃金、時間外・休日・深夜割増、精皆勤・通勤・家族手当は除いて判定する。",topic:"短時間労働者"},
 {id:"X5-043",s:5,q:"大学の夜間学部に在学する学生は、短時間労働者の学生除外の対象とならない。",a:true,e:"学生除外(3条1項9号)は昼間学生が対象。夜間・通信・定時制の学生、休学中の学生は除外されず、要件を満たせば被保険者となる。",topic:"短時間労働者"},
 {id:"X5-044",s:5,q:"特定適用事業所に該当しない事業所でも、労使の合意に基づき申出をすることにより、短時間労働者の適用を受けることができる。",a:true,e:"任意特定適用事業所(年金制度改正法の附則による制度)。被保険者等の2分の1以上の同意を得て申出をする。",topic:"短時間労働者"},
 {id:"X5-045",s:5,q:"個人経営の適用事業所の事業主本人は、その事業所の被保険者となる。",a:false,e:"個人事業主は使用される者ではないため被保険者とならない。法人の代表者・役員は法人に使用される者として被保険者となり得る(通達)。",topic:"被保険者"},
 {id:"X5-046",s:5,q:"労働者派遣事業の派遣労働者は、派遣元事業主の事業所の被保険者となる。",a:true,e:"派遣労働者は派遣元と雇用関係があるため派遣元の被保険者となる(通達)。保険料の負担・納付も派遣元事業主が行う。",topic:"被保険者"},
 {id:"X5-047",s:5,q:"試用期間を設けて採用された者は、試用期間が終了し本採用となった日に被保険者の資格を取得する。",a:false,e:"試用期間中も使用関係があるため、雇入れ日(試用期間の初日)に資格を取得する(35条・通達)。",topic:"資格取得"},
 {id:"X5-048",s:5,q:"適用事業所に使用されるに至った者は、その者に最初の報酬が支払われた日に被保険者の資格を取得する。",a:false,e:"資格取得日は適用事業所に使用されるに至った日(35条)。報酬の支払日ではない。事実上の使用関係の発生日で判断する。",topic:"資格取得"},
 {id:"X5-049",s:5,q:"健康保険の被保険者が4月10日に死亡したときは、同日である4月10日に被保険者の資格を喪失する。",a:false,e:"死亡による喪失は死亡日の翌日で、この例では4月11日(36条1号)。当日喪失となるのは後期高齢者医療の被保険者となった場合など。退職も翌日喪失。",topic:"資格喪失"},
 {id:"X5-050",s:5,q:"被保険者が75歳に達したときは、75歳の誕生日の翌日に被保険者の資格を喪失する。",a:false,e:"75歳に達すると後期高齢者医療の被保険者となり、その日(誕生日当日)に資格を喪失する(3条1項7号・36条)。翌日ではない。",topic:"資格喪失"},
 {id:"X5-051",s:5,q:"同時に2以上の事業所に使用される被保険者で保険者が異なるときは、被保険者はその事実があった日から10日以内に保険者を選択して届け出なければならない。",a:true,e:"施行規則1条のとおり、二以上事業所勤務届。標準報酬月額は各事業所の報酬を合算して決定し、保険料は報酬額で按分する。",topic:"二以上事業所勤務"},
 {id:"X5-052",s:5,q:"婚姻の届出をしていないが事実上婚姻関係と同様の事情にある者は、被保険者により主として生計を維持されていれば被扶養者となることができる。",a:true,e:"3条7項1号の配偶者には事実婚を含む。同一世帯要件は不要で、生計維持関係だけでよい。",topic:"被扶養者"},
 {id:"X5-053",s:5,q:"被保険者と事実婚関係にある配偶者の父母は、被保険者と同一の世帯に属し、主として被保険者により生計を維持されていれば被扶養者となることができる。",a:true,e:"3条7項3号のとおり。事実婚の配偶者本人は生計維持のみで足りるが、その父母・子は同一世帯要件も必要。",topic:"被扶養者"},
 {id:"X5-054",s:5,q:"事実婚関係の配偶者が死亡した後も、その父母が引き続き被保険者と同一の世帯に属し生計を維持されていれば、被扶養者となり得る。",a:true,e:"3条7項4号のとおり。事実婚配偶者の死亡後における父母・子も、同一世帯・生計維持なら被扶養者となる。",topic:"被扶養者"},
 {id:"X5-055",s:5,q:"被保険者の叔父は3親等内の親族であるから、被保険者と同一の世帯に属し主として被保険者により生計を維持されていれば被扶養者となることができる。",a:true,e:"3条7項2号のとおり。直系尊属・配偶者・子・孫・兄弟姉妹以外の3親等内の親族は、同一世帯+生計維持で被扶養者となる。",topic:"被扶養者"},
 {id:"X5-056",s:5,q:"被保険者の孫が被扶養者となるためには、被保険者と同一の世帯に属していることが必要である。",a:false,e:"孫は直系卑属として3条7項1号のグループに属し、生計維持関係のみで足りる。同一世帯要件は不要。",topic:"被扶養者"},
 {id:"X5-057",s:5,q:"被保険者の祖父母が被扶養者となるためには、被保険者と同一の世帯に属していることが必要である。",a:false,e:"祖父母は直系尊属であり、生計維持関係のみで被扶養者となる(3条7項1号)。同一世帯要件は不要。",topic:"被扶養者"},
 {id:"X5-058",s:5,q:"被扶養者の国内居住要件については、外国において留学をする学生は例外として扱われ、日本国内に住所がなくても被扶養者となり得る。",a:true,e:"令和2年4月施行の国内居住要件(3条7項ただし書)の例外。留学生、海外赴任に同行する家族等は国内に生活の基礎があると認められる。",topic:"被扶養者"},
 {id:"X5-059",s:5,q:"被保険者の被扶養者であった者が75歳に達して後期高齢者医療の被保険者となったときは、被扶養者に該当しなくなる。",a:true,e:"3条7項ただし書により、後期高齢者医療の被保険者等は被扶養者から除かれる。75歳到達日に後期高齢者医療へ移行し、健保の被扶養者でなくなる。",topic:"被扶養者"},
 {id:"X5-060",s:5,q:"被扶養者の認定において、認定対象者が被保険者と同一世帯に属していない場合は、年間収入が130万円未満であり、かつ、被保険者の年間収入の2分の1未満であれば被扶養者に該当する。",a:false,e:"別居の場合は、年収130万円未満かつ被保険者からの援助(仕送り)額より少ないことが基準(通達)。2分の1未満は同居の場合の基準。",topic:"被扶養者"},
 {id:"X5-061",s:5,q:"被扶養者の認定における年間収入は、過去の収入実績ではなく、認定時点以降の年間の見込み収入額で判断する。",a:true,e:"通達により、年間収入は認定時点から将来に向かっての見込みで判断する。前年の実績ではない。",topic:"被扶養者"},
 {id:"X5-062",s:5,q:"被扶養者の認定における年間収入には、障害年金や遺族年金などの非課税の公的年金は含まれない。",a:false,e:"被扶養者認定の年間収入には、障害年金・遺族年金など非課税の収入や雇用保険の給付も含まれる(通達)。税法上の所得とは異なる。",topic:"被扶養者"},
 {id:"X5-063",s:5,q:"被扶養者の認定において、19歳以上23歳未満の者(被保険者の配偶者を除く)の年間収入の基準は150万円未満とされている(2026年4月時点)。",a:true,e:"令和7年10月1日から、19歳以上23歳未満の者(配偶者を除く)の収入要件は150万円未満に引き上げられた(認定基準の通知改正)。(2026年4月時点)",topic:"被扶養者"},
 {id:"X5-064",s:5,q:"事業主は、被保険者の資格喪失の事実があった日から5日以内に、資格喪失届を日本年金機構又は健康保険組合に提出しなければならない。",a:true,e:"48条・施行規則のとおり。資格取得届・資格喪失届・賞与支払届はいずれも5日以内。算定基礎届は7月1日〜10日、月額変更届は速やかに提出。",topic:"届出"},
 {id:"X5-065",s:5,q:"被保険者の資格の取得及び喪失の確認は、事業主の届出若しくは被保険者等の請求により、又は職権で行われる。",a:true,e:"39条2項のとおり。確認によって資格の得喪の効力が生じる(39条1項)。任意継続・特例退職被保険者は確認不要。",topic:"確認"},
 {id:"X5-066",s:5,q:"被保険者又は被保険者であった者は、事業主の同意を得た場合に限り、被保険者の資格の取得及び喪失の確認を請求することができる。",a:false,e:"被保険者等はいつでも確認を請求できる(51条1項)。事業主の同意は不要。届出を怠る事業主から被保険者を保護する趣旨。",topic:"確認"},
 {id:"X5-067",s:5,q:"事業主は、被保険者の資格の取得・喪失の確認又は標準報酬の決定・改定があったときは、その旨を被保険者又は被保険者であった者に通知しなければならない。",a:true,e:"49条2項のとおり。保険者等から事業主に通知され、事業主はこれを被保険者等に通知する。",topic:"確認"},
 {id:"X5-068",s:5,q:"被保険者証は、2024年12月2日以降新たに発行されなくなり、医療機関での資格確認はマイナンバーカードによる電子資格確認が基本となった(2026年4月時点)。",a:true,e:"令和5年改正で被保険者証の交付規定を削除(令和6年12月2日施行)。電子資格確認(3条13項)が基本。(2026年4月時点)",topic:"資格確認"},
 {id:"X5-069",s:5,q:"マイナンバーカードによる電子資格確認を受けることができない被保険者には、保険者から資格確認書が交付される(2026年4月時点)。",a:true,e:"被保険者証廃止に伴い、マイナ保険証を利用できない者等に保険者が資格確認書を交付する(令和6年12月2日施行)。(2026年4月時点)",topic:"資格確認"},
 {id:"X5-070",s:5,q:"事業主は、健康保険に関する書類を、その完結の日から5年間保存しなければならない。",a:false,e:"健康保険に関する書類の保存期間は、その完結の日から2年間(施行規則34条)。5年は誤り。",topic:"書類保存"},
 {id:"X5-071",s:5,q:"通勤手当は、実費弁償的な性格を有するため、健康保険の報酬には含まれない。",a:false,e:"通勤手当は労働の対償として受けるものであり報酬に含まれる(3条5項・通達)。定期券を現物で支給する場合も同様。",topic:"報酬"},
 {id:"X5-072",s:5,q:"事業主が恩恵的に支給する結婚祝金や病気見舞金は、健康保険の報酬に含まれない。",a:true,e:"労働の対償ではない恩恵的給付であり報酬に当たらない(3条5項・通達)。臨時に受けるものも報酬から除かれる。",topic:"報酬"},
 {id:"X5-073",s:5,q:"業務のための出張旅費として実費弁償的に支給されるものは、健康保険の報酬に含まれない。",a:true,e:"出張旅費は業務遂行のための実費弁償であり労働の対償ではないので報酬に含まない(通達)。",topic:"報酬"},
 {id:"X5-074",s:5,q:"賞与の名称で支給されるものであっても、年4回以上支給されるものは、標準賞与額ではなく標準報酬月額の算定の基礎となる報酬に含まれる。",a:true,e:"賞与は3月を超える期間ごとに受けるもの(3条6項)。年4回以上支給されるものは報酬として標準報酬月額に算入する(通達)。",topic:"報酬"},
 {id:"X5-075",s:5,q:"食事や住宅など報酬の一部が現物で支給される場合、その価額は、全国健康保険協会の理事長が定める。",a:false,e:"現物給与の価額は、その地方の時価によって厚生労働大臣が定める(46条1項)。健康保険組合は規約で別段の定めができる(46条2項)。",topic:"報酬"},
 {id:"X5-076",s:5,q:"日、時間、出来高又は請負によって報酬が定められる被保険者の資格取得時の報酬月額は、資格取得月前1月間に同一事業所で同様の業務に従事し同様の報酬を受けた者の報酬の平均額とする。",a:true,e:"42条1項2号のとおり。月給等の場合は取得日現在の報酬額を月額換算する(同項1号)。",topic:"資格取得時決定"},
 {id:"X5-077",s:5,q:"資格取得時決定において報酬月額の算定が困難な場合は、資格取得の月前1月間にその地方で同様の業務に従事し同様の報酬を受けた者の報酬の額を報酬月額とする。",a:true,e:"42条1項3号のとおり。月給等は取得日現在の報酬を月額換算(1号)、日給等は前1月間の同事業所の同種者の平均(2号)、算定困難ならその地方の同種者(3号)。",topic:"資格取得時決定"},
 {id:"X5-078",s:5,q:"5月20日に資格を取得した被保険者の資格取得時決定による標準報酬月額は、翌年の8月まで適用される。",a:false,e:"1月1日〜5月31日の取得はその年の8月まで適用(42条2項)。翌年8月までとなるのは6月1日〜12月31日に取得した場合。",topic:"資格取得時決定"},
 {id:"X5-079",s:5,q:"6月20日に被保険者の資格を取得した者については、その年の定時決定は行われない。",a:true,e:"6月1日から7月1日までの間に資格を取得した者は定時決定の対象外(41条3項)。資格取得時決定が翌年8月まで適用される。",topic:"定時決定"},
 {id:"X5-080",s:5,q:"7月に随時改定が行われる被保険者であっても、その年の定時決定は行われ、随時改定と定時決定の両方が適用される。",a:false,e:"7月から9月までのいずれかの月から随時改定・育児休業等終了時改定・産前産後休業終了時改定が行われる者は定時決定の対象外(41条3項)。",topic:"定時決定"},
 {id:"X5-081",s:5,q:"定時決定では、4月から6月までのうち報酬の支払基礎日数が17日未満の月があるときは、その月を除いて報酬月額を算定する。",a:true,e:"41条1項のとおり。一般の被保険者は17日未満の月を除く。特定適用事業所等の短時間労働者は11日未満の月を除く。",topic:"定時決定"},
 {id:"X5-082",s:5,q:"特定適用事業所に使用される短時間労働者の定時決定では、報酬の支払基礎日数が15日未満の月を除いて報酬月額を算定する。",a:false,e:"短時間労働者(4分の3基準を満たさない者)は支払基礎日数11日未満の月を除く(41条1項・施行規則)。15日は4分の3以上のパート(短時間就労者)の特例の話。",topic:"定時決定"},
 {id:"X5-083",s:5,q:"4月から6月までの間に昇給差額が遡って支払われた場合、定時決定ではその差額を含めずに報酬月額を算定する。",a:true,e:"遡及支払分は当該月の報酬ではないため、それを除いて算定する保険者算定の扱い(44条・通達)。",topic:"保険者算定"},
 {id:"X5-084",s:5,q:"業務の性質上、例年季節的に報酬が変動する被保険者について、4月から6月の報酬で算定した額と前年7月から当年6月までの報酬の平均で算定した額に著しい差があるときは、事業主の申立てにより年間平均による保険者算定ができる。",a:true,e:"44条・通達による年間報酬の平均での保険者算定。事業主の申立書に被保険者の同意書を添付して行う。",topic:"保険者算定"},
 {id:"X5-085",s:5,q:"随時改定による標準報酬月額は、報酬の変動があった月から起算して3月目の月から改定される。",a:false,e:"変動月から継続した3月間の報酬で判断し、4月目の月から改定する(43条1項)。3月目としたのが誤り。",topic:"随時改定"},
 {id:"X5-086",s:5,q:"8月に固定的賃金が変動し、11月から随時改定された標準報酬月額は、翌年の8月まで適用される。",a:true,e:"7月から12月までに改定された場合は翌年8月まで、1月から6月までに改定された場合はその年の8月まで適用(43条2項)。",topic:"随時改定"},
 {id:"X5-087",s:5,q:"固定的賃金が増額したが、残業手当の減少により3か月の報酬の平均額が従前より2等級以上低下した場合には、随時改定により標準報酬月額が引き下げられる。",a:false,e:"固定的賃金の増額と報酬総額の低下という逆方向の変動の場合は随時改定を行わない(通達)。変動の方向が一致することが必要。",topic:"随時改定"},
 {id:"X5-088",s:5,q:"随時改定は、固定的賃金の変動月以後の継続した3か月のいずれの月も報酬の支払基礎日数が17日以上あることが要件である。",a:true,e:"43条1項・通達。3か月のうち1月でも17日未満の月があれば随時改定は行わない(短時間労働者は11日)。",topic:"随時改定"},
 {id:"X5-089",s:5,q:"固定的賃金の変動がなく、残業手当などの非固定的賃金のみが大幅に増加して2等級以上の差が生じた場合でも、随時改定が行われる。",a:false,e:"随時改定は昇給・降給など固定的賃金の変動が前提(通達)。非固定的賃金の増減だけでは随時改定の対象とならない。",topic:"随時改定"},
 {id:"X5-090",s:5,q:"育児休業等終了時改定は、育児休業等を終了した日においてその育児休業等に係る1歳未満の子を養育する被保険者が対象となる。",a:false,e:"対象は3歳未満の子を養育する被保険者(43条の2第1項)。1歳未満としたのが誤り。事業主を経由して保険者等に申し出る。",topic:"育児休業等終了時改定"},
 {id:"X5-091",s:5,q:"育児休業等終了時改定による標準報酬月額は、育児休業等終了日の翌日が属する月から改定される。",a:false,e:"終了日の翌日が属する月以後3月間の報酬で算定し、その3月を経過した日の属する月の翌月(4月目)から改定(43条の2第2項)。",topic:"育児休業等終了時改定"},
 {id:"X5-092",s:5,q:"育児休業等終了時改定は、被保険者の申出に基づいて行われるものであり、保険者等が職権で行うものではない。",a:true,e:"43条の2第1項のとおり。被保険者が事業主を経由して申し出る。固定的賃金の変動や2等級以上の差は要件でない。",topic:"育児休業等終了時改定"},
 {id:"X5-093",s:5,q:"厚生年金保険の3歳未満の子を養育する期間の標準報酬月額の特例に相当する制度は、健康保険にも設けられている。",a:false,e:"養育期間の従前標準報酬月額のみなし措置は厚生年金保険法26条の制度で、健康保険にはない。健保の給付・保険料は実際の標準報酬月額による。",topic:"標準報酬月額"},
 {id:"X5-094",s:5,q:"毎年3月31日における最高等級の被保険者数の割合が100分の1.5を超え、その状態が継続すると認められるときは、その年の9月1日から、政令で最高等級の上に等級を加える改定ができる。",a:true,e:"40条2項のとおり。ただし改定後の最高等級に該当する被保険者の割合が100分の0.5を下回ってはならない。",topic:"標準報酬月額"},
 {id:"X5-095",s:5,q:"標準報酬月額の等級区分の上限の改定は、社会保障審議会の議を経て、厚生労働大臣の告示により行われる。",a:false,e:"等級の追加改定は政令で行う(40条2項)。また厚生労働大臣は政令の制定・改正の立案にあたり社会保障審議会の意見を聴く(40条3項)。告示ではない。",topic:"標準報酬月額"},
 {id:"X5-096",s:5,q:"標準賞与額は、被保険者が受けた賞与額に1,000円未満の端数があるときはこれを切り捨てて決定する。",a:true,e:"45条1項のとおり。年度(4月1日〜翌年3月31日)の累計額が573万円を超える場合は573万円とする。",topic:"標準賞与額"},
 {id:"X5-097",s:5,q:"標準賞与額の上限である573万円は、毎年1月1日から12月31日までの暦年の累計額で判断する。",a:false,e:"累計は毎年4月1日から翌年3月31日までの年度単位(45条1項)。暦年としたのが誤り。",topic:"標準賞与額"},
 {id:"X5-098",s:5,q:"同一年度内に転職し保険者が変わった場合、前の保険者で決定された標準賞与額は新しい保険者での年度累計573万円の算定に含まれない。",a:true,e:"年度累計は同一の保険者ごとに行う(45条・通達)。同一保険者内であれば事業所が変わっても合算する。",topic:"標準賞与額"},
 {id:"X5-099",s:5,q:"事業主は、被保険者に賞与を支払った日から10日以内に、賞与支払届を提出しなければならない。",a:false,e:"賞与支払届の提出期限は賞与支払日から5日以内(48条・施行規則)。10日は誤り。",topic:"届出"},
 {id:"X5-100",s:5,q:"事業主は、毎年7月1日現在の被保険者について、7月31日までに報酬月額算定基礎届を提出しなければならない。",a:false,e:"算定基礎届の提出期限は7月1日から7月10日まで(施行規則25条)。7月31日としたのが誤り。",topic:"届出"},
 {id:"X5-101",s:5,q:"被保険者及び事業主は、一般保険料額及び介護保険料額の各2分の1を負担する。",a:true,e:"161条1項のとおり。任意継続被保険者は全額自己負担。健康保険組合は規約で事業主負担割合を増加できる(162条)。",topic:"保険料の負担"},
 {id:"X5-102",s:5,q:"事業主は、その使用する被保険者及び自己の負担する保険料を納付する義務を負う。",a:true,e:"161条2項のとおり。被保険者負担分も含め事業主が納付義務を負い、被保険者負担分は報酬・賞与から控除できる(167条)。任継は本人が納付。",topic:"保険料の納付"},
 {id:"X5-103",s:5,q:"毎月の保険料は、当月末日までに納付しなければならない。",a:false,e:"毎月の保険料は翌月末日までに納付する(164条1項)。任意継続被保険者はその月の10日まで(初月は保険者が指定する日)。",topic:"保険料の納付"},
 {id:"X5-104",s:5,q:"事業主は、被保険者に通貨で報酬を支払う場合、被保険者の負担すべき当月分の保険料を当月の報酬から控除することができる。",a:false,e:"報酬から控除できるのは前月分の保険料(167条1項)。ただし資格を喪失した場合は前月分及び当月分を控除できる。",topic:"保険料の控除"},
 {id:"X5-105",s:5,q:"被保険者が月末で退職し資格を喪失した場合、事業主はその月の報酬から前月分及びその月分の保険料を控除することができる。",a:true,e:"167条1項ただし書のとおり。資格喪失した被保険者については前月分と当月分をまとめて控除できる。",topic:"保険料の控除"},
 {id:"X5-106",s:5,q:"事業主は、被保険者に賞与を支払う場合、その賞与に係る被保険者負担分の保険料を当該賞与から控除することができる。",a:true,e:"167条2項のとおり。標準賞与額に係る保険料は賞与から控除する。控除したときは計算書を作成して被保険者に通知する(同条3項)。",topic:"保険料の控除"},
 {id:"X5-107",s:5,q:"事業主は、保険料を報酬から控除したときは、保険料の控除に関する計算書を作成し、その控除額を被保険者に通知しなければならない。",a:true,e:"167条3項のとおり。報酬・賞与から保険料を控除したときは計算書を作成し、控除額を被保険者に通知する(給与明細等)。",topic:"保険料の控除"},
 {id:"X5-108",s:5,q:"被保険者が月の途中で資格を取得し、同じ月の途中で資格を喪失した場合、その月の保険料は徴収されない。",a:false,e:"同月得喪の場合は、その月を1か月として保険料を徴収する(156条3項の反対解釈)。原則(取得月から喪失月の前月まで)の例外。",topic:"保険料の徴収期間"},
 {id:"X5-109",s:5,q:"3月31日に退職した被保険者は4月1日に資格を喪失するため、3月分の保険料が徴収される。",a:true,e:"退職日の翌日が喪失日(36条)。喪失月(4月)の前月である3月分までが徴収対象(156条3項)。",topic:"保険料の徴収期間"},
 {id:"X5-110",s:5,q:"3月30日に退職した被保険者(3月は31日まである)は3月31日に資格を喪失するため、3月分の保険料も徴収される。",a:false,e:"喪失日は3月31日で、喪失月は3月。保険料は喪失月の前月(2月分)までで、3月分は徴収されない(156条3項)。",topic:"保険料の徴収期間"},
 {id:"X5-111",s:5,q:"健康保険組合は、規約で定めることにより、40歳未満又は65歳以上の被保険者で40歳以上65歳未満の被扶養者がある者(特定被保険者)から介護保険料額を徴収することができる。",a:true,e:"附則7条の特定被保険者の制度。被扶養者は介護保険の第2号被保険者でも保険料を個別に負担しないため、被保険者から徴収できる。",topic:"介護保険料"},
 {id:"X5-112",s:5,q:"全国健康保険協会の介護保険料率は、都道府県単位保険料率と同様に、支部ごとに異なる率が定められる。",a:false,e:"協会の介護保険料率は全国一律(160条)。支部ごとに異なるのは一般保険料率(都道府県単位保険料率)のほう。",topic:"介護保険料"},
 {id:"X5-113",s:5,q:"医療保険者は、2026年4月分の保険料から、子ども・子育て支援金を医療保険料と併せて被保険者等から徴収している(2026年4月時点)。",a:true,e:"子ども・子育て支援法の改正(令和6年)により、支援金は令和8年(2026年)4月分から医療保険料と併せて徴収。(2026年4月時点)",topic:"子ども・子育て支援金"},
 {id:"X5-114",s:5,q:"育児休業等を開始した日の属する月にその育児休業等を終了した場合でも、その月における育児休業等の日数が14日以上であれば、その月の保険料は免除される。",a:true,e:"159条1項(令和4年10月改正)。月末時点で休業していなくても、同月内に14日以上取得すれば当該月の保険料が免除される。",topic:"保険料の免除"},
 {id:"X5-115",s:5,q:"賞与を支払った月の末日に育児休業等をしていれば、育児休業等の期間の長さにかかわらず、その賞与に係る保険料は免除される。",a:false,e:"賞与に係る保険料の免除は、連続して1月を超える育児休業等をした場合に限られる(159条1項、令和4年10月改正)。短期取得での免除は不可。",topic:"保険料の免除"},
 {id:"X5-116",s:5,q:"育児休業等期間中の保険料の免除は、事業主が保険者等に申出をすることにより、被保険者負担分及び事業主負担分の双方について行われる。",a:true,e:"159条1項のとおり。本人分・事業主分とも免除される。任意継続被保険者には育休免除はない。",topic:"保険料の免除"},
 {id:"X5-117",s:5,q:"被保険者が刑事施設に拘禁され保険給付が制限されている期間は、その被保険者に被扶養者がいる場合であっても保険料は徴収されない。",a:false,e:"118条該当期間の保険料不徴収(158条)は被扶養者がいない場合に限る。被扶養者には家族給付が行われるため、被扶養者がいれば保険料は徴収される。",topic:"保険料の免除"},
 {id:"X5-118",s:5,q:"任意継続被保険者の保険料は、その月の10日までに納付しなければならない。ただし、初めて納付すべき保険料については、保険者が指定する日までに納付する。",a:true,e:"164条1項ただし書のとおり。納付期日までに納付しないと、原則として納付期日の翌日に資格を喪失する(38条3号)。",topic:"保険料の納付"},
 {id:"X5-119",s:5,q:"任意継続被保険者は、4月から9月まで、10月から翌年3月まで、又は4月から翌年3月までの期間を単位として保険料を前納することができる。",a:true,e:"165条・施行令のとおり。前納額は年4分の利率による複利現価法で割り引いた額となる。",topic:"保険料の前納"},
 {id:"X5-120",s:5,q:"任意継続被保険者が保険料を前納する場合の前納額は、年5分の利率による単利計算で割り引いた額とされる。",a:false,e:"前納額は年4分の利率による複利現価法で計算する(施行令)。年5分・単利としたのが誤り。",topic:"保険料の前納"},
 {id:"X5-121",s:5,q:"全国健康保険協会が管掌する健康保険の一般の被保険者に係る保険料は、厚生労働大臣(日本年金機構)が徴収する。",a:true,e:"155条のとおり。協会管掌の一般被保険者の保険料は大臣(実務は日本年金機構)が徴収し、任意継続被保険者の保険料は協会が徴収する。",topic:"保険料の徴収"},
 {id:"X5-122",s:5,q:"全国健康保険協会が管掌する任意継続被保険者の保険料は、日本年金機構が徴収する。",a:false,e:"任意継続被保険者の保険料は協会が徴収する(155条1項)。日本年金機構が徴収するのは協会管掌の一般被保険者の保険料。",topic:"保険料の徴収"},
 {id:"X5-123",s:5,q:"納付義務者が国税の滞納処分を受けるとき、強制執行を受けるとき、破産手続開始の決定を受けたとき、法人が解散したとき等は、保険料を納期前であってもすべて徴収することができる。",a:true,e:"172条の繰上徴収。強制執行・破産手続開始・企業担保権の実行・競売開始・法人の解散・事業の廃止等も事由。この場合は督促状を要しない。",topic:"繰上徴収"},
 {id:"X5-124",s:5,q:"適用事業所の事業主が住所を移転したときは、保険料の繰上徴収の事由に該当する。",a:false,e:"住所移転は繰上徴収の事由ではない(172条)。事由は滞納処分・強制執行・破産・競売・法人の解散・事業の廃止・船舶の滅失等。",topic:"繰上徴収"},
 {id:"X5-125",s:5,q:"保険料を滞納する者に督促状を発する場合、その指定期限は、督促状を発する日から起算して7日以上を経過した日でなければならない。",a:false,e:"督促状の指定期限は、発する日から起算して10日以上を経過した日(180条)。7日は誤り。",topic:"督促"},
 {id:"X5-126",s:5,q:"督促に係る保険料額が1,000円未満であるときは、延滞金は徴収されない。",a:true,e:"181条1項ただし書のとおり。また延滞金額が100円未満であるときも徴収しない(181条)。",topic:"延滞金"},
 {id:"X5-127",s:5,q:"督促状に指定した期限までに保険料を完納した場合であっても、納期限の翌日から完納の日の前日までの延滞金は必ず徴収される。",a:false,e:"督促状の指定期限までに完納したときは延滞金を徴収しない(181条)。保険料額1,000円未満、延滞金100円未満の場合も徴収しない。",topic:"延滞金"},
 {id:"X5-128",s:5,q:"保険料等の先取特権の順位は、国税及び地方税に優先する。",a:false,e:"保険料等の先取特権の順位は、国税及び地方税に次ぐ(182条)。優先するのではない。",topic:"先取特権"},
 {id:"X5-129",s:5,q:"保険料の口座振替による納付は、納付義務者の申出がなくとも、保険者等が職権で行うことができる。",a:false,e:"口座振替による納付は、納付義務者から申出があった場合に、納付が確実と認められ、かつ有利と認められるときに承認できる(166条)。",topic:"口座振替"},
 {id:"X5-130",s:5,q:"被保険者の標準賞与額に係る保険料額は、標準賞与額に一般保険料率(介護保険第2号被保険者は介護保険料率を加えた率)を乗じて得た額である。",a:true,e:"156条1項のとおり。任意継続被保険者には賞与がないため標準賞与額に係る保険料はない。",topic:"保険料"},
 {id:"X5-131",s:5,q:"健康保険組合は、保険料の滞納者に対して、厚生労働大臣の認可を受けることなく、国税滞納処分の例によって処分することができる。",a:false,e:"健康保険組合が国税滞納処分の例により処分するには厚生労働大臣の認可が必要(180条)。市町村に処分を請求することもできる。",topic:"保険料の滞納処分"},
 {id:"X5-132",s:5,q:"任意継続被保険者の保険料は、資格喪失時に使用されていた事業所の事業主が2分の1を負担し続ける。",a:false,e:"任意継続被保険者は事業主と使用関係がないため、保険料は全額自己負担(161条1項ただし書)。",topic:"保険料の負担"},
 {id:"X5-133",s:5,q:"産前産後休業期間中の保険料の免除は、産前産後休業を開始した日の属する月から、終了する日の翌日が属する月の前月までの期間について行われる。",a:true,e:"159条の3のとおり。育児休業等の免除と同じく、開始月から終了日の翌日が属する月の前月まで。事業主の申出による。",topic:"保険料の免除"},
 {id:"X5-134",s:5,q:"病院又は診療所への入院に伴う食事の提供は、療養の給付に含まれる。",a:false,e:"食事療養は療養の給付から除かれ(63条2項1号)、入院時食事療養費として給付される(85条)。",topic:"療養の給付"},
 {id:"X5-135",s:5,q:"評価療養、患者申出療養及び選定療養は、療養の給付に含まれない。",a:true,e:"63条2項3号〜5号のとおり。これらを受けたときは保険外併用療養費の対象となる(86条)。",topic:"療養の給付"},
 {id:"X5-136",s:5,q:"居宅における療養上の管理及びその療養に伴う世話その他の看護は、療養の給付の範囲に含まれる。",a:true,e:"63条1項4号のとおり。診察、薬剤・治療材料の支給、処置・手術その他の治療、入院・看護と並ぶ療養の給付の範囲。",topic:"療養の給付"},
 {id:"X5-137",s:5,q:"被保険者が療養の給付を受けようとするときは、保険者が指定する保険医療機関で受けなければならず、被保険者が自由に選ぶことはできない。",a:false,e:"被保険者は保険医療機関・保険薬局等のうち自己の選定するものから療養の給付を受ける(63条3項)。自由に選択できる。",topic:"療養の給付"},
 {id:"X5-138",s:5,q:"保険医療機関又は保険薬局の指定は、指定の日から起算して6年を経過したときは、その効力を失う。",a:true,e:"68条1項のとおり。医師本人のみ等の一定の診療所は、別段の申出がなければ指定の更新の申請があったものとみなされる(68条2項)。",topic:"保険医療機関"},
 {id:"X5-139",s:5,q:"保険医療機関の指定は、病院又は診療所の開設者の申請により、全国健康保険協会が行う。",a:false,e:"保険医療機関の指定は開設者の申請により厚生労働大臣が行う(65条1項)。協会ではない。",topic:"保険医療機関"},
 {id:"X5-140",s:5,q:"保険医療機関は、2週間以上の予告期間を設けて、その指定を辞退することができる。",a:false,e:"指定の辞退は1月以上の予告期間を設けて行う(79条1項)。保険医・保険薬剤師の登録抹消の求めも1月以上の予告期間(79条2項)。",topic:"保険医療機関"},
 {id:"X5-141",s:5,q:"保険医の登録は、医師又は歯科医師の申請により厚生労働大臣が行う。",a:true,e:"64条・71条1項のとおり。保険医療機関で診療に従事する医師は保険医でなければならない。保険医の登録には有効期間がない。",topic:"保険医"},
 {id:"X5-142",s:5,q:"事業主が設置する診療所であって保険者が指定したもので療養の給付を受けることもできる。",a:true,e:"63条3項2号のとおり。特定の保険者が管掌する被保険者に対して診療を行う病院等で保険者が指定したものでも受けられる。健保組合直営病院も同様(3号)。",topic:"療養の給付"},
 {id:"X5-143",s:5,q:"70歳以上の被保険者の一部負担金の割合は、原則として、70歳に達する日の属する月の翌月以後の療養から2割となる。",a:true,e:"74条1項2号のとおり。70歳に達する日(誕生日の前日)の属する月の翌月以後。現役並み所得者は3割(同項3号)。",topic:"一部負担金"},
 {id:"X5-144",s:5,q:"70歳以上の被保険者が現役並み所得者として3割負担となるのは、療養を受ける月の標準報酬月額が38万円以上である場合である。",a:false,e:"現役並み所得者の基準は標準報酬月額28万円以上(74条1項3号・施行令)。ただし収入額が基準未満であれば申請により2割となる。",topic:"一部負担金"},
 {id:"X5-145",s:5,q:"標準報酬月額が28万円以上の70歳以上の被保険者であっても、被保険者及び被扶養者の収入の額が政令で定める額に満たない者は、申請により一部負担金の割合が2割となる。",a:true,e:"74条1項3号・施行令のとおり。収入基準を下回ることを申請すれば現役並み所得者に該当しない。",topic:"一部負担金"},
 {id:"X5-146",s:5,q:"保険者は、災害その他の特別の事情がある被保険者で保険医療機関等に一部負担金を支払うことが困難であると認められるものに対し、一部負担金の減額、免除又は徴収猶予の措置をとることができる。",a:true,e:"75条の2のとおり。減額・免除のほか、保険医療機関に対する支払に代えて保険者が直接徴収し、その徴収を猶予する措置もある。",topic:"一部負担金"},
 {id:"X5-147",s:5,q:"保険医療機関が善良な管理者と同一の注意をもって一部負担金の支払を受けることに努めたにもかかわらず被保険者が支払わないときは、保険者は、保険医療機関の請求に基づき、この法律の規定による徴収金の例によりこれを処分することができる。",a:true,e:"74条2項のとおり。保険医療機関が善管注意をもって支払を求めても一部負担金が支払われないとき、その請求により保険者が徴収金の例で処分できる。",topic:"一部負担金"},
 {id:"X5-148",s:5,q:"6歳に達する日以後の最初の3月31日以前の被扶養者に係る家族療養費の給付割合は100分の90である。",a:false,e:"義務教育就学前の被扶養者の家族療養費の給付割合は100分の80(自己負担2割)(110条2項)。原則は100分の70。",topic:"家族療養費"},
 {id:"X5-149",s:5,q:"70歳以上の被扶養者に係る家族療養費の給付割合は、被保険者が現役並み所得者である場合を除き、100分の80である。",a:true,e:"110条2項のとおり。現役並み所得者の被保険者の70歳以上の被扶養者は100分の70となる。",topic:"家族療養費"},
 {id:"X5-150",s:5,q:"入院時生活療養費は、療養病床に入院する70歳以上の被保険者が生活療養を受けたときに支給される。",a:false,e:"対象は療養病床に入院する65歳以上の被保険者(特定長期入院被保険者、63条2項2号・85条の2)。70歳ではない。",topic:"入院時生活療養費"},
 {id:"X5-151",s:5,q:"生活療養とは、食事の提供である療養並びに温度、照明及び給水に関する適切な療養環境の形成である療養をいう。",a:true,e:"63条2項2号のとおり。65歳以上の療養病床入院者は、食事療養費ではなく入院時生活療養費の対象となる。",topic:"入院時生活療養費"},
 {id:"X5-152",s:5,q:"入院時食事療養費は、保険者が被保険者に代わって保険医療機関に支払うことができ、その支払があったときは被保険者に支給があったものとみなされる。",a:true,e:"85条のとおり(代理受領による現物給付化)。被保険者は食事療養標準負担額だけを窓口で支払う。",topic:"入院時食事療養費"},
 {id:"X5-153",s:5,q:"入院時食事療養費の額は、食事療養に要する平均的な費用の額を勘案して算定した額から、全国健康保険協会が定める食事療養標準負担額を控除した額である。",a:false,e:"食事療養標準負担額は、平均的な家計における食費の状況等を勘案して厚生労働大臣が定める(85条2項)。協会が定めるのではない。",topic:"入院時食事療養費"},
 {id:"X5-154",s:5,q:"保険医療機関の特別の療養環境の病室(いわゆる差額ベッド)の提供は、評価療養に該当する。",a:false,e:"特別の療養環境の提供は、被保険者の選定に係る選定療養に該当する(63条2項5号)。評価療養は先進医療・治験等の将来の保険導入を評価するもの。",topic:"保険外併用療養費"},
 {id:"X5-155",s:5,q:"病床数200以上の病院で他の医療機関からの紹介なしに受けた初診は、選定療養に該当する。",a:true,e:"選定療養(63条2項5号・告示)の一つ。予約診療、時間外診療、180日を超える入院なども選定療養。",topic:"保険外併用療養費"},
 {id:"X5-156",s:5,q:"先進医療や医薬品の治験に係る診療は、選定療養に該当する。",a:false,e:"先進医療・治験に係る診療は評価療養に該当する(63条2項3号)。保険導入のための評価を行うもの。",topic:"保険外併用療養費"},
 {id:"X5-157",s:5,q:"患者申出療養は、保険医療機関の申出を起点として、厚生労働大臣が定める高度の医療技術を用いた療養である。",a:false,e:"患者申出療養は、患者本人の申出を起点とする(63条2項4号・4項)。申出は臨床研究中核病院の開設者の意見書等を添えて行う。",topic:"保険外併用療養費"},
 {id:"X5-158",s:5,q:"保険外併用療養費の支給対象となる療養を受けた場合、保険外の部分の費用は被保険者の自己負担となり、保険診療と共通する基礎的部分が保険外併用療養費として給付される。",a:true,e:"86条のとおり。基礎的部分から一部負担金相当額を控除した額が給付され、代理受領による現物給付化がされる。",topic:"保険外併用療養費"},
 {id:"X5-159",s:5,q:"被保険者が、緊急その他やむを得ない事情がないのに、自らの判断で保険医療機関以外の病院で診療を受けた場合でも、療養費は支給される。",a:false,e:"療養費は、療養の給付等が困難と保険者が認めるとき、又はやむを得ないと認めるときに支給される(87条1項)。自由な選択による受診では支給されない。",topic:"療養費"},
 {id:"X5-160",s:5,q:"被保険者が海外旅行中に急病となり現地の医療機関で診療を受けた場合、保険者がやむを得ないと認めれば療養費が支給され得る。",a:true,e:"87条1項による海外療養費。額は日本国内で同様の療養を受けた場合の費用を基準に算定し、実費を超えない。",topic:"療養費"},
 {id:"X5-161",s:5,q:"療養費の額は、療養に要した実際の費用の額が療養の給付の算定基準による額を上回る場合には、実際の費用の額から一部負担金相当額を控除した額となる。",a:false,e:"療養費は療養の給付の基準で算定した費用額(実費がそれより少なければ実費)から一部負担金相当額を控除した額(87条2項)。実費が基準額を上回っても基準額が上限。",topic:"療養費"},
 {id:"X5-162",s:5,q:"柔道整復師による打撲や捻挫の施術は、医師の同意がなくても療養費の支給対象となり得る。",a:true,e:"柔道整復の療養費は、骨折・脱臼の施術は応急手当を除き医師の同意が必要だが、打撲・捻挫は医師の同意を要しない(通達)。",topic:"療養費"},
 {id:"X5-163",s:5,q:"医師の指示によりコルセット等の治療用装具を作成した場合、その費用について療養費の支給対象となり得る。",a:true,e:"治療用装具は療養の給付として現物支給できないため、保険者がやむを得ないと認め療養費として支給する(87条・通達)。",topic:"療養費"},
 {id:"X5-164",s:5,q:"訪問看護療養費は、居宅で継続して療養を受ける状態にある被保険者が、指定訪問看護を受けた場合に支給されるが、主治医の指示は要件とされていない。",a:false,e:"指定訪問看護は、主治医がその治療の必要の程度につき厚生労働省令で定める基準に適合していると認めたものに限られる(88条1項)。",topic:"訪問看護療養費"},
 {id:"X5-165",s:5,q:"指定訪問看護を受けた被保険者は、療養の給付の一部負担金と同じ割合による基本利用料を指定訪問看護事業者に支払う。",a:true,e:"88条のとおり。基本利用料の割合は一部負担金と同じ(3割・2割等)。食事療養の標準負担額に相当するものはない。",topic:"訪問看護療養費"},
 {id:"X5-166",s:5,q:"指定訪問看護事業者の指定は、訪問看護事業を行う者の申請により、都道府県知事が行う。",a:false,e:"指定訪問看護事業者の指定は厚生労働大臣が行う(88条1項・89条)。介護保険の指定居宅サービス事業者の指定(都道府県知事)と混同しない。",topic:"訪問看護療養費"},
 {id:"X5-167",s:5,q:"移送費は、原則として保険者の事前の承認を必要とするが、緊急その他やむを得ない場合は事後の承認でもよいとされている。",a:true,e:"97条・施行規則・通達のとおり。移送により適切な療養を受けたこと、移動困難、緊急その他やむを得ないことの3要件を保険者が認める。",topic:"移送費"},
 {id:"X5-168",s:5,q:"移送費の額は、実際に移送に要した費用の額であり、最も経済的な通常の経路及び方法により算定した額を上回っても実費全額が支給される。",a:false,e:"移送費は最も経済的な通常の経路・方法で移送された場合の費用により算定した額で、実費を超えられない(97条1項・施行規則)。実費全額ではない。",topic:"移送費"},
 {id:"X5-169",s:5,q:"被扶養者が保険者の承認を受けて移送されたときは、被保険者に対して家族移送費が支給される。",a:true,e:"112条のとおり。家族移送費の額は移送費と同じく最も経済的な通常の経路・方法で算定し、実費を超えない。被扶養者ではなく被保険者に支給。",topic:"移送費"},
 {id:"X5-170",s:5,q:"高額療養費は、同一の月における自己負担額について算定され、月をまたぐ入院の場合は各月ごとに判断する。",a:true,e:"115条・施行令41条。暦月単位で算定するため、月をまたぐ入院は月ごとに分けて自己負担限度額と比較する。",topic:"高額療養費"},
 {id:"X5-171",s:5,q:"70歳未満の者の高額療養費の算定において、同一の医療機関で受けた入院と外来の自己負担額は、同じ月であれば区別せずに一つとして計算する。",a:false,e:"同一医療機関でも入院と外来、医科と歯科は別々に計算する(施行令・通達)。院外処方の調剤は処方元の医療機関と合わせて計算する。",topic:"高額療養費"},
 {id:"X5-172",s:5,q:"保険医療機関の処方箋に基づき保険薬局で調剤を受けた場合の自己負担額は、処方箋を交付した医療機関での自己負担額と合わせて1つの医療機関の額として取り扱う。",a:true,e:"施行令・通達のとおり。院外処方による調剤は処方元医療機関と合算して、70歳未満の21,000円基準を判断する。",topic:"高額療養費"},
 {id:"X5-173",s:5,q:"70歳以上の者の高額療養費の算定においても、70歳未満の者と同様に、21,000円以上の自己負担額のみが合算の対象となる。",a:false,e:"70歳以上の者は自己負担額の多寡を問わずすべて合算できる(施行令41条)。21,000円以上に限るのは70歳未満の者。",topic:"高額療養費"},
 {id:"X5-174",s:5,q:"共働きの夫婦がそれぞれ別の保険者の被保険者である場合でも、同一世帯であれば夫婦の自己負担額を合算して高額療養費を算定できる。",a:false,e:"世帯合算は同一の保険者の被保険者とその被扶養者の間で行う(施行令41条)。別々の保険者の被保険者同士は合算できない。",topic:"高額療養費"},
 {id:"X5-175",s:5,q:"多数回該当の判定において、高額療養費の支給回数は、同一の保険者における支給に限って数える。",a:true,e:"施行令42条・通達。保険者が変わると回数は通算しない。協会けんぽ内での都道府県支部の移動は同一保険者なので通算する。",topic:"高額療養費"},
 {id:"X5-176",s:5,q:"人工透析を要する慢性腎不全、血友病などの長期にわたり高額な療養を要する特定疾病の場合、高額療養費の自己負担限度額は原則1万円とされている。",a:true,e:"施行令の長期高額疾病の特例。70歳未満の上位所得者で人工透析を要する者は2万円。",topic:"高額療養費"},
 {id:"X5-177",s:5,q:"入院時食事療養費に係る食事療養標準負担額や、差額ベッドの費用は、高額療養費の算定の対象となる自己負担額に含まれる。",a:false,e:"高額療養費の対象は一部負担金等の保険診療の自己負担。食事療養標準負担額・生活療養標準負担額や保険外の差額ベッド代は含まれない(115条・施行令)。",topic:"高額療養費"},
 {id:"X5-178",s:5,q:"高額療養費は、被保険者のほか、被扶養者の療養に係る自己負担額についても対象となり、被保険者に支給される。",a:true,e:"115条のとおり。高額療養費は被保険者に支給され、被扶養者分の自己負担も世帯合算の対象となる。",topic:"高額療養費"},
 {id:"X5-179",s:5,q:"高額療養費は、被保険者が70歳以上の場合に限り支給される給付である。",a:false,e:"高額療養費は年齢を問わず支給される(115条)。自己負担限度額が70歳未満と70歳以上で区分されているにすぎない。",topic:"高額療養費"},
 {id:"X5-180",s:5,q:"高額介護合算療養費は、医療保険と介護保険の両方に自己負担がある世帯について、年間の自己負担の合計額が基準額を超えた場合に支給される。",a:true,e:"115条の2のとおり。計算期間は8月1日から翌年7月31日まで。介護保険側からは高額医療合算介護サービス費が按分して支給される。",topic:"高額介護合算療養費"},
 {id:"X5-181",s:5,q:"高額介護合算療養費は、介護保険の自己負担額がなく医療保険の自己負担額だけが高額な世帯についても支給される。",a:false,e:"高額介護合算療養費は医療と介護の両方の自己負担を合算する制度(115条の2)。どちらか一方しかない場合は対象とならない。",topic:"高額介護合算療養費"},
 {id:"X5-182",s:5,q:"被保険者の疾病が労働者災害補償保険法の業務災害に当たる場合には、健康保険の保険給付は行われない。",a:true,e:"健保の目的は業務災害以外の疾病等(1条)であり、労災保険の給付を受けられる場合には健保の給付を行わない(55条)。",topic:"給付の調整"},
 {id:"X5-183",s:5,q:"介護保険法の規定により療養に相当する給付を受けることができる場合には、健康保険の療養の給付等は行われない。",a:true,e:"55条のとおり。介護保険の給付が優先し、同一の療養について健保の給付は行わない。",topic:"給付の調整"},
 {id:"X5-184",s:5,q:"被保険者が法人の役員である場合、その法人の役員としての業務に起因する疾病・負傷については、被保険者数が5人未満の適用事業所で従業員と著しく異ならない業務に従事している場合を除き、保険給付は行われない。",a:true,e:"53条の2のとおり。役員業務の傷病は原則として健保の給付対象外だが、小規模(5人未満)事業所の従業員並み業務の役員は例外。",topic:"法人の役員"},
 {id:"X5-185",s:5,q:"給付事由が第三者の行為によって生じた場合において、保険者が保険給付を行ったときは、その給付の価額の限度で、被保険者が第三者に対して有する損害賠償請求権を取得する。",a:true,e:"57条1項のとおり(代位取得)。被保険者が先に損害賠償を受けたときは、その価額の限度で保険給付を行う責を免れる(同条2項)。",topic:"第三者行為"},
 {id:"X5-186",s:5,q:"交通事故の被害者である被保険者が加害者から損害賠償を受けた場合でも、保険者は同一の事由について保険給付の全額を行わなければならない。",a:false,e:"被保険者が第三者から同一事由について損害賠償を受けたときは、保険者はその価額の限度で保険給付を行う責を免れる(57条2項)。",topic:"第三者行為"},
 {id:"X5-187",s:5,q:"被保険者が第三者の行為によって負傷した場合、健康保険による療養の給付を受けることはできず、加害者に治療費を請求しなければならない。",a:false,e:"第三者行為による傷病でも療養の給付を受けられる。保険者は給付後、損害賠償請求権を代位取得する(57条1項)。届出が必要。",topic:"第三者行為"},
 {id:"X5-188",s:5,q:"傷病手当金の待期期間には、年次有給休暇を取得して報酬を受けた日は含まれない。",a:false,e:"待期は労務不能の日が連続3日あればよく、報酬の有無を問わないため有給休暇の日や公休日も含む(99条・通達)。",topic:"傷病手当金"},
 {id:"X5-189",s:5,q:"就業時間中に業務外の事由で負傷し、その日のうちに労務不能となった場合、その翌日から待期期間を起算する。",a:false,e:"就業時間中に労務不能となった場合はその日から待期を起算する(通達)。就業時間後に労務不能となった場合は翌日から起算。",topic:"傷病手当金"},
 {id:"X5-190",s:5,q:"保険診療ではなく自費診療で療養を受けている場合であっても、療養のため労務に服することができなければ傷病手当金の支給対象となり得る。",a:true,e:"99条の療養は健保の療養の給付に限られず、自費診療や病後の自宅静養も含む(通達)。",topic:"傷病手当金"},
 {id:"X5-191",s:5,q:"傷病手当金の額は、支給開始日の属する月以前の直近の継続した12月間の各月の標準報酬月額を平均した額の30分の1に相当する額の3分の2に相当する額である。",a:true,e:"99条2項のとおり。被保険者期間が12月に満たない場合は、その期間の平均額と全被保険者の平均額のいずれか少ない額を用いる。",topic:"傷病手当金"},
 {id:"X5-192",s:5,q:"支給開始日の属する月以前の被保険者期間が12月に満たない者の傷病手当金は、その期間の標準報酬月額の平均額と全被保険者の標準報酬月額の平均額のいずれか多い額を基礎として算定する。",a:false,e:"いずれか少ない額を基礎とする(99条2項ただし書)。比較対象は被保険者期間の平均額と、前年度9月30日の全被保険者の平均額。",topic:"傷病手当金"},
 {id:"X5-193",s:5,q:"出産手当金を支給する場合には、その期間の傷病手当金は支給されないが、傷病手当金の額が出産手当金の額を上回るときは、その差額が支給される。",a:true,e:"103条1項のとおり。平成28年改正で出産手当金優先・差額支給の仕組みとなった。",topic:"傷病手当金"},
 {id:"X5-194",s:5,q:"同一の傷病について障害厚生年金を受けることができるときは、傷病手当金は一切支給されない。",a:false,e:"障害厚生年金の額(障害基礎年金を含む)を360で除した額が傷病手当金の日額より少ないときは、その差額が支給される(108条)。",topic:"傷病手当金"},
 {id:"X5-195",s:5,q:"同一の傷病について厚生年金保険法による障害手当金を受けることができるときは、傷病手当金の額の合計額が障害手当金の額に達するまでの間、傷病手当金は支給されない。",a:true,e:"108条のとおり。一時金である障害手当金とは、受けるべき傷病手当金の合計額が障害手当金の額に達するまで支給しない形で調整する。",topic:"傷病手当金"},
 {id:"X5-196",s:5,q:"在職中の被保険者が老齢厚生年金を受けている場合、傷病手当金は老齢厚生年金との調整により減額される。",a:false,e:"老齢退職年金給付との調整は資格喪失後の継続給付を受ける者に限られる(108条)。在職中の被保険者の傷病手当金は調整されない。",topic:"傷病手当金"},
 {id:"X5-197",s:5,q:"任意継続被保険者は、療養のため労務に服することができないときであっても、任意継続被保険者として傷病手当金を受けることはできない。",a:true,e:"99条1項は任意継続被保険者を除いている。ただし資格喪失後の継続給付(104条)の要件を満たす場合は受けられる。",topic:"傷病手当金"},
 {id:"X5-198",s:5,q:"資格喪失後の傷病手当金の継続給付の要件である継続1年以上の被保険者期間には、任意継続被保険者であった期間も含まれる。",a:false,e:"継続1年以上の被保険者期間には任意継続被保険者の期間を含まない(104条かっこ書)。特例退職被保険者期間も含まない。",topic:"傷病手当金"},
 {id:"X5-199",s:5,q:"退職日に出勤した者は、資格喪失の日の前日に傷病手当金を受けている状態にないため、資格喪失後の傷病手当金の継続給付を受けることができない。",a:true,e:"継続給付は資格喪失の際に傷病手当金を受けているか受けられる状態であることが要件(104条)。退職日に出勤すれば労務不能でなく要件を欠く(通達)。",topic:"傷病手当金"},
 {id:"X5-200",s:5,q:"資格喪失後の継続給付として傷病手当金を受けていた者が、いったん労務可能となった後、同一の傷病で再び労務不能となった場合は、傷病手当金の支給が再開される。",a:false,e:"継続給付はいったん労務可能となり支給が途切れると、その後再び労務不能となっても支給されない(通達)。",topic:"傷病手当金"},
 {id:"X5-201",s:5,q:"偽りその他不正の行為により保険給付を受けた者に対しては、6月以内の期間を定め、傷病手当金又は出産手当金の全部又は一部を支給しない旨の決定をすることができる。",a:true,e:"120条のとおり。ただし偽り等があった日から1年を経過したときはこの限りでない。",topic:"傷病手当金"},
 {id:"X5-202",s:5,q:"被保険者が報酬の全部を受けられる期間であっても、療養のため労務不能であれば傷病手当金は全額支給される。",a:false,e:"報酬の全部又は一部を受けられる期間は傷病手当金を支給しない。ただし報酬が手当の額より少ないときは差額を支給(108条)。",topic:"傷病手当金"},
 {id:"X5-203",s:5,q:"出産育児一時金の支給対象となる出産は、妊娠4か月(85日)以上の出産をいい、死産や流産も含まれる。",a:true,e:"通達により、健保の出産は妊娠85日以上の分娩で、生産・死産・流産・人工妊娠中絶を問わない。",topic:"出産育児一時金"},
 {id:"X5-204",s:5,q:"妊娠85日以上の人工妊娠中絶は、正常な出産ではないため出産育児一時金の支給対象とならない。",a:false,e:"妊娠85日以上であれば人工妊娠中絶も出産に含まれ、出産育児一時金が支給される(101条・通達)。",topic:"出産育児一時金"},
 {id:"X5-205",s:5,q:"双子を出産した場合、出産育児一時金は1児分のみ支給される。",a:false,e:"出産育児一時金は1児ごとに支給されるため、双子なら2児分となる(101条・施行令36条)。",topic:"出産育児一時金"},
 {id:"X5-206",s:5,q:"出産育児一時金の直接支払制度を利用した場合で、出産費用が出産育児一時金の額を下回るときは、その差額を被保険者が保険者に請求できる。",a:true,e:"直接支払制度では保険者が医療機関等に一時金を直接支払う。出産費用が一時金より少なければ差額が被保険者に支給される。",topic:"出産育児一時金"},
 {id:"X5-207",s:5,q:"資格喪失後6月以内に出産した者が、夫の被扶養者にもなっている場合には、資格喪失後の出産育児一時金と家族出産育児一時金の両方を受けることができる。",a:false,e:"いずれか一方を選択して受ける(通達)。同一の出産について重複して支給されることはない。",topic:"出産育児一時金"},
 {id:"X5-208",s:5,q:"家族出産育児一時金は、被保険者の被扶養者である配偶者が出産した場合に限り支給される。",a:false,e:"家族出産育児一時金は被扶養者が出産したときに支給される(114条)。配偶者に限らず、被扶養者である娘等の出産でも支給される。",topic:"家族出産育児一時金"},
 {id:"X5-209",s:5,q:"資格喪失後に出産育児一時金を受けるためには、資格喪失日の前日まで継続して1年以上被保険者であった者が、資格喪失後6月以内に出産したことが必要である。",a:true,e:"106条のとおり。継続1年以上の被保険者期間には任意継続被保険者期間を含まない。",topic:"出産育児一時金"},
 {id:"X5-210",s:5,q:"出産が出産予定日より遅れた場合、出産予定日後出産日までの期間についても出産手当金が支給される。",a:true,e:"出産日以前の期間は出産予定日以前42日から実際の出産日までとなり、遅れた期間も支給対象(102条・通達)。",topic:"出産手当金"},
 {id:"X5-211",s:5,q:"出産手当金の支給期間において、出産日当日は出産日後の期間に含まれる。",a:false,e:"出産日当日は出産日以前の期間(産前)に含まれる(102条・通達)。産後56日は出産日の翌日から数える。",topic:"出産手当金"},
 {id:"X5-212",s:5,q:"任意継続被保険者が出産したときは、出産手当金は支給されないが、出産育児一時金は支給される。",a:true,e:"出産手当金は任意継続被保険者を除く(102条1項)。出産育児一時金は任意継続被保険者にも支給される(101条)。",topic:"出産手当金"},
 {id:"X5-213",s:5,q:"出産手当金の額は、1日につき、標準報酬日額相当額(直近12月の平均による額)の3分の2に相当する額である。",a:true,e:"102条2項により傷病手当金の額の算定(99条2項)を準用。直近の継続12月間の標準報酬月額の平均の30分の1の3分の2。報酬を受ける日は差額支給。",topic:"出産手当金"},
 {id:"X5-214",s:5,q:"資格喪失の際に出産手当金を受けていた者が資格喪失後も継続給付を受けるには、資格喪失日の前日まで継続して6月以上被保険者であったことが必要である。",a:false,e:"継続給付の要件は継続して1年以上被保険者(任意継続被保険者期間を除く)であったこと(104条)。6月としたのが誤り。",topic:"出産手当金"},
 {id:"X5-215",s:5,q:"妊娠85日以上の死産の場合には、出産手当金は支給されない。",a:false,e:"妊娠85日以上の死産も出産に含まれるため、要件を満たせば出産手当金が支給される(102条・通達)。",topic:"出産手当金"},
 {id:"X5-216",s:5,q:"被扶養者が死亡したときは、被保険者に対して、被保険者の標準報酬月額に相当する額が家族埋葬料として支給される。",a:false,e:"家族埋葬料は定額5万円(113条・施行令35条)。標準報酬月額相当額は旧制度の埋葬料の考え方で、現在は定額。",topic:"家族埋葬料"},
 {id:"X5-217",s:5,q:"被扶養者である妻が妊娠5か月で死産した場合、その死産児について家族埋葬料が支給される。",a:false,e:"死産児は被扶養者に該当しないため家族埋葬料は支給されない(通達)。死産は出産として家族出産育児一時金の対象となる。",topic:"家族埋葬料"},
 {id:"X5-218",s:5,q:"埋葬料の支給を受ける者は、被保険者により生計を維持していた者であって埋葬を行うものであればよく、被保険者と同一世帯であったことは要しない。",a:true,e:"100条1項・通達のとおり。生計の一部を維持されていれば足り、被扶養者や同一世帯である必要はない。",topic:"埋葬料"},
 {id:"X5-219",s:5,q:"被保険者が自殺した場合は、故意に給付事由を生じさせたものとして埋葬料は支給されない。",a:false,e:"自殺による死亡でも埋葬料は支給される(通達)。116条の故意の給付制限は死亡に関する給付である埋葬料には及ばない扱い。",topic:"埋葬料"},
 {id:"X5-220",s:5,q:"被保険者であった者が、資格喪失後3月以内に死亡したときは、被保険者期間の長短にかかわらず、埋葬料の支給対象となる。",a:true,e:"105条1項のとおり。資格喪失後3月以内の死亡には継続1年以上の被保険者期間要件はない。",topic:"資格喪失後の給付"},
 {id:"X5-221",s:5,q:"資格喪失後の傷病手当金の継続給付を受けていた者がその給付を受けなくなった日後6月以内に死亡した場合、埋葬料が支給される。",a:false,e:"継続給付を受けなくなった日後3月以内に死亡したときに埋葬料が支給される(105条1項)。6月ではない。継続給付受給中の死亡も対象。",topic:"資格喪失後の給付"},
 {id:"X5-222",s:5,q:"資格喪失後の埋葬料の支給は、資格喪失日の前日まで継続して1年以上被保険者であった者に限られる。",a:false,e:"喪失後3月以内の死亡等による埋葬料(105条)には継続1年以上の要件はない。1年要件は傷病手当金・出産手当金の継続給付と出産育児一時金。",topic:"資格喪失後の給付"},
 {id:"X5-223",s:5,q:"任意継続被保険者となるための申出は、資格喪失日から20日以内にしなければならないが、保険者は、正当な理由があると認めるときは、この期間経過後の申出であっても受理することができる。",a:true,e:"37条1項ただし書のとおり。天災等の正当な理由があれば20日経過後でも受理できる。",topic:"任意継続被保険者"},
 {id:"X5-224",s:5,q:"任意継続被保険者の資格は、任意継続被保険者となった日から起算して3年を経過した日の翌日に喪失する。",a:false,e:"任意継続被保険者でいられるのは2年まで。2年を経過した日の翌日に資格を喪失する(38条)。",topic:"任意継続被保険者"},
 {id:"X5-225",s:5,q:"任意継続被保険者が適用事業所に使用されて一般の被保険者となったときは、その日の翌日に任意継続被保険者の資格を喪失する。",a:false,e:"被保険者となったときは、その日に任意継続被保険者の資格を喪失する(38条)。翌日ではない。船員保険の被保険者・後期高齢者となった場合もその日。",topic:"任意継続被保険者"},
 {id:"X5-226",s:5,q:"任意継続被保険者が保険料を納付期日までに納付しなかったときは、正当な理由があると保険者が認めた場合を除き、納付期日の翌日に資格を喪失する。",a:true,e:"38条のとおり。初めて納付すべき保険料を納付しなかった場合は、任意継続被保険者とならなかったものとみなされる(37条2項)。",topic:"任意継続被保険者"},
 {id:"X5-227",s:5,q:"任意継続被保険者が資格喪失を申し出たときは、その申出が受理された日に資格を喪失する。",a:false,e:"申出が受理された日の属する月の末日の翌日に喪失する(38条、令和4年1月施行)。受理日当日ではない。",topic:"任意継続被保険者"},
 {id:"X5-228",s:5,q:"任意継続被保険者には標準賞与額に係る保険料はなく、また、育児休業期間中の保険料免除の規定も適用されない。",a:true,e:"任意継続被保険者は事業所に使用されていないため賞与も育休免除(159条)もない。保険料は全額自己負担。",topic:"任意継続被保険者"},
 {id:"X5-229",s:5,q:"健康保険組合は、規約で定めることにより、任意継続被保険者の標準報酬月額を資格喪失時の標準報酬月額とすることができる。",a:true,e:"47条(令和4年1月施行)。資格喪失時の額が平均額を上回る場合でも、組合は規約で喪失時の額とすることができる。協会にこの特例はない。",topic:"任意継続被保険者"},
 {id:"X5-230",s:5,q:"任意継続被保険者となった者の被扶養者は、任意継続被保険者の被扶養者として家族療養費等の給付を受けることはできない。",a:false,e:"任意継続被保険者にも被扶養者に関する給付(家族療養費等)が行われる。除かれるのは本人の傷病手当金・出産手当金。",topic:"任意継続被保険者"},
 {id:"X5-231",s:5,q:"任意継続被保険者の資格は、その資格を取得しようとする者の申出により、資格喪失日の翌日に取得する。",a:false,e:"任意継続被保険者の資格は、一般被保険者の資格を喪失した日(退職日の翌日)に取得し、空白は生じない(37条)。喪失日のさらに翌日ではない。",topic:"任意継続被保険者"},
 {id:"X5-232",s:5,q:"特例退職被保険者には、傷病手当金及び出産手当金は支給されない。",a:true,e:"附則3条により、特例退職被保険者には任意継続被保険者と同様に傷病手当金・出産手当金は支給されない。",topic:"特例退職被保険者"},
 {id:"X5-233",s:5,q:"特例退職被保険者の保険料は、特定健康保険組合の規約に基づき、元の事業主が2分の1を負担する。",a:false,e:"特例退職被保険者の保険料は全額自己負担(附則3条)。使用関係がないため事業主負担はない。",topic:"特例退職被保険者"},
 {id:"X5-234",s:5,q:"特例退職被保険者が後期高齢者医療の被保険者となったときは、特例退職被保険者の資格を喪失する。",a:true,e:"附則3条のとおり。75歳到達で後期高齢者医療の被保険者となり、その日に資格を喪失する。特定健康保険組合の規約で定める制度。",topic:"特例退職被保険者"},
 {id:"X5-235",s:5,q:"特例退職被保険者の制度は、全国健康保険協会も厚生労働大臣の認可を受けて実施することができる。",a:false,e:"特例退職被保険者の制度を実施できるのは、厚生労働大臣の認可を受けた特定健康保険組合に限られる(附則3条1項)。協会は実施できない。",topic:"特例退職被保険者"},
 {id:"X5-236",s:5,q:"日雇労働者であっても、後期高齢者医療の被保険者である者は、日雇特例被保険者とならない。",a:true,e:"3条2項ただし書により、後期高齢者医療の被保険者等は日雇特例被保険者とならない。2月間26日未満見込み等は大臣の承認で除外される。",topic:"日雇特例被保険者"},
 {id:"X5-237",s:5,q:"適用事業所に使用される日雇労働者で、継続する2月間に通算して26日以上使用される見込みのないことが明らかであるときは、厚生労働大臣の承認を受けて日雇特例被保険者とならないことができる。",a:true,e:"3条2項ただし書1号のとおり。任意継続被保険者である場合や、農業等の本業がある場合も承認を受けて適用除外となれる。",topic:"日雇特例被保険者"},
 {id:"X5-238",s:5,q:"日雇労働者は、日雇特例被保険者となった日から起算して10日以内に、日雇特例被保険者手帳の交付を申請しなければならない。",a:false,e:"手帳の交付申請は日雇特例被保険者となった日から起算して5日以内(126条)。10日ではない。",topic:"日雇特例被保険者"},
 {id:"X5-239",s:5,q:"日雇特例被保険者の療養の給付の支給期間は、同一の傷病について給付を開始した日から1年間(結核性疾病は5年間)である。",a:true,e:"129条のとおり。同一傷病につき給付開始から1年(結核性疾病は5年)が限度。一般の被保険者には療養の給付の期間制限はない点と対比。",topic:"日雇特例被保険者"},
 {id:"X5-240",s:5,q:"日雇特例被保険者の傷病手当金の支給期間は、同一の傷病について支給を始めた日から起算して1年6月である。",a:false,e:"日雇特例被保険者の傷病手当金は6月(厚生労働大臣指定の疾病は1年6月)が限度(135条)。一般の通算1年6か月と混同しない。",topic:"日雇特例被保険者"},
 {id:"X5-241",s:5,q:"初めて日雇特例被保険者手帳の交付を受けた者が、受給資格の保険料納付要件を満たす前に療養を受けたときは、特別療養費が支給される。",a:true,e:"145条のとおり。手帳交付月の初日から3月間(月の初日以外に交付の場合は4月間)の特例。",topic:"日雇特例被保険者"},
 {id:"X5-242",s:5,q:"日雇特例被保険者の出産育児一時金は、出産日の属する月前2月間に通算して26日分以上の保険料が納付されていることが要件である。",a:false,e:"出産に関する給付の要件は、出産日の属する月前4月間に通算26日分以上の保険料納付(137条)。2月間26日・6月間78日は療養の給付等の要件。",topic:"日雇特例被保険者"},
 {id:"X5-243",s:5,q:"日雇特例被保険者が死亡した場合、その者により生計を維持していた者で埋葬を行うものに対して埋葬料が支給される。",a:true,e:"136条のとおり。死亡日の属する月前2月間に26日分以上又は前6月間に78日分以上の納付等が要件。",topic:"日雇特例被保険者"},
 {id:"X5-244",s:5,q:"日雇特例被保険者の傷病手当金は、一般の被保険者と異なり待期期間の定めはなく、労務不能となった初日から支給される。",a:false,e:"日雇特例被保険者の傷病手当金も継続した3日間の待期がある(135条)。4日目から支給。",topic:"日雇特例被保険者"},
 {id:"X5-245",s:5,q:"日雇特例被保険者の保険料の納付は、事業主が日雇特例被保険者手帳に健康保険印紙をはり、これに消印して行う方法のほか、厚生労働大臣の承認を受けて印紙保険料納付計器を使用する方法がある。",a:true,e:"169条のとおり。計器による納付印の表示で印紙の貼付・消印に代えることができる。",topic:"日雇特例被保険者"},
 {id:"X5-246",s:5,q:"日雇特例被保険者の被扶養者が療養を受けた場合には、家族療養費は支給されない。",a:false,e:"日雇特例被保険者の被扶養者の療養についても、保険料納付要件を満たせば家族療養費が支給される(140条)。家族埋葬料・家族出産育児一時金もある。",topic:"日雇特例被保険者"},
 {id:"X5-247",s:5,q:"被保険者が自己の故意の犯罪行為により給付事由を生じさせたときは、当該給付事由に係る保険給付の全部又は一部を行わないことができる。",a:false,e:"故意の犯罪行為・故意の事故は保険給付を「行わない」(116条)。絶対的制限であり、「行わないことができる」ではない。",topic:"給付制限"},
 {id:"X5-248",s:5,q:"被保険者が闘争、泥酔又は著しい不行跡によって給付事由を生じさせたときは、当該給付事由に係る保険給付の全部又は一部を行わないことができる。",a:true,e:"117条のとおり相対的制限。故意の犯罪行為・故意の事故は「行わない」(116条)という絶対的制限であり、効果の違いが頻出。",topic:"給付制限"},
 {id:"X5-249",s:5,q:"被保険者が少年院に収容されたときは、その期間は、被保険者本人だけでなく、その被扶養者に係る保険給付も行われない。",a:false,e:"118条1項により被保険者本人の給付は行わないが、被扶養者に係る保険給付は行われる(118条2項)。",topic:"給付制限"},
 {id:"X5-250",s:5,q:"被保険者が正当な理由なしに療養に関する指示に従わないときは、保険給付の全部を行わないことができる。",a:false,e:"療養の指示に従わない場合は保険給付の「一部」を行わないことができる(119条)。全部ではない。",topic:"給付制限"},
 {id:"X5-251",s:5,q:"保険者は、被保険者が正当な理由なしに文書の提出命令に従わず、又は当該職員の質問に答弁しないときは、保険給付の全部又は一部を行わないことができる。",a:true,e:"121条のとおり。保険者の文書提出命令・質問や診断に正当な理由なく従わないときは、保険給付の全部又は一部を行わないことができる。",topic:"給付制限"},
 {id:"X5-252",s:5,q:"偽りその他不正の行為による傷病手当金等の支給制限は、偽り等があった日から3年を経過したときは行うことができない。",a:false,e:"120条ただし書により、偽り等があった日から1年を経過したときは支給制限をすることができない。3年ではない。",topic:"給付制限"},
 {id:"X5-253",s:5,q:"保険給付を受ける権利は、譲り渡し、担保に供し、又は差し押さえることができない。",a:true,e:"61条のとおり受給権の譲渡・担保提供・差押えは禁止。年金のような例外(国税滞納処分等)はない。租税その他の公課も課されない(62条)。",topic:"受給権の保護"},
 {id:"X5-254",s:5,q:"傷病手当金は所得保障の性格を有するため、所得税の課税対象となる。",a:false,e:"租税その他の公課は保険給付として支給を受けた金品を標準として課することができない(62条)。傷病手当金も非課税。",topic:"公課の禁止"},
 {id:"X5-255",s:5,q:"事業主が虚偽の報告又は証明をしたために保険給付が行われたときは、保険者は、その事業主に対し、保険給付を受けた者に連帯して徴収金を納付すべきことを命ずることができる。",a:true,e:"58条2項のとおり。事業主の虚偽報告や、医師・歯科医師等の虚偽の診断書により不正受給があったときは、受給者と連帯して納付させることができる。",topic:"不正利得"},
 {id:"X5-256",s:5,q:"保険医療機関が偽りその他不正の行為によって療養の給付に関する費用の支払を受けたときは、保険者はその支払った額の返還に加え、その返還額に100分の40を乗じた額を支払わせることができる。",a:true,e:"58条3項のとおり。保険医療機関・保険薬局の不正請求には、返還額に加えその100分の40を乗じた額(加算金)を支払わせることができる。",topic:"不正利得"},
 {id:"X5-257",s:5,q:"被保険者の資格に関する処分に対する社会保険審査官への審査請求は、処分があったことを知った日の翌日から起算して6月以内にしなければならない。",a:false,e:"審査請求期間は処分があったことを知った日の翌日から起算して3月以内(社会保険審査官及び社会保険審査会法4条)。",topic:"不服申立て"},
 {id:"X5-258",s:5,q:"審査請求をした日から3月以内に社会保険審査官の決定がないときは、審査請求人は、審査請求が棄却されたものとみなすことができる。",a:false,e:"棄却みなしは審査請求をした日から2月以内に決定がないとき(189条2項)。3月は審査請求期間(知った日の翌日から3月以内)と混同。",topic:"不服申立て"},
 {id:"X5-259",s:5,q:"保険料の賦課又は徴収の処分に不服がある者は、社会保険審査会に対して審査請求をすることができる。",a:true,e:"190条のとおり。保険料等の処分は社会保険審査会への一審制。資格・標準報酬・保険給付の処分は審査官→審査会の二審制。",topic:"不服申立て"},
 {id:"X5-260",s:5,q:"被保険者の資格又は標準報酬に関する処分が確定したときは、その処分についての不服を、当該処分に基づく保険給付に関する処分についての不服の理由とすることができない。",a:true,e:"189条4項のとおり。確定した資格等の処分を、給付処分の不服申立てで蒸し返すことはできない。",topic:"不服申立て"},
 {id:"X5-261",s:5,q:"被保険者の資格に関する処分の取消しの訴えは、社会保険審査官への審査請求を経ることなく、直ちに提起することができる。",a:false,e:"資格・標準報酬・保険給付の処分の取消訴訟は、社会保険審査官の決定を経た後でなければ提起できない(192条)。審査会の裁決までは不要。",topic:"不服申立て"},
 {id:"X5-262",s:5,q:"被保険者の資格、標準報酬又は保険給付に関する処分に対する審査請求は、時効の完成猶予及び更新に関しては、裁判上の請求とみなされる。",a:true,e:"189条3項のとおり。審査請求中に保険給付の受給権の時効が完成しないようにする趣旨。",topic:"不服申立て"},
 {id:"X5-263",s:5,q:"保険料等を徴収し、又はその還付を受ける権利は、これらを行使することができる時から2年を経過したときは、時効によって消滅する。",a:true,e:"193条1項のとおり。保険給付を受ける権利も同じく2年。保険料等の納入の告知・督促には時効の更新の効力がある(193条2項)。",topic:"時効"},
 {id:"X5-264",s:5,q:"保険料等の納入の告知又は督促には、時効の更新の効力はない。",a:false,e:"保険料等の納入の告知又は督促は、時効の更新の効力を有する(193条2項)。徴収権の時効は2年で、告知・督促により新たに進行する。",topic:"時効"},
 {id:"X5-265",s:5,q:"傷病手当金を受ける権利の消滅時効は、労務不能であった日ごとに、その翌日から起算する。",a:true,e:"193条1項・通達。傷病手当金は各日ごとに権利が発生するため、日ごとにその翌日から2年。",topic:"時効"},
 {id:"X5-266",s:5,q:"療養費を受ける権利の消滅時効は、療養を受けた日の翌日から起算する。",a:false,e:"療養費の時効は、療養に要した費用を支払った日の翌日から起算する(通達)。受診日ではない。",topic:"時効"},
 {id:"X5-267",s:5,q:"高額療養費を受ける権利の消滅時効は、原則として診療を受けた月の翌月の1日から起算する。",a:true,e:"通達のとおり。ただし診療費の自己負担分を翌月以後に支払ったときは、支払った日の翌日から起算する。",topic:"時効"},
 {id:"X5-268",s:5,q:"埋葬料を受ける権利の消滅時効は、埋葬を行った日の翌日から起算する。",a:false,e:"埋葬料の時効は死亡日の翌日から起算する(通達)。埋葬費は埋葬を行った日の翌日から起算する点と区別する。",topic:"時効"},
 {id:"X5-269",s:5,q:"出産育児一時金を受ける権利の消滅時効は、出産日の翌日から起算して2年である。",a:true,e:"193条1項・通達のとおり。出産手当金は労務に服さなかった日ごとにその翌日から起算する。",topic:"時効"},
 {id:"X5-270",s:5,q:"被保険者が死亡した場合、その者に支給すべき保険給付でまだ支給しなかったものがあるときは、健康保険法の未支給給付の規定により、配偶者、子、父母の順で請求できる。",a:false,e:"健康保険法には国民年金法・厚生年金保険法のような未支給給付の規定はなく、未支給分は民法の相続により相続人が請求する(通達)。",topic:"保険給付の通則"},
 {id:"X5-271",s:5,q:"保険者は、高齢者の医療の確保に関する法律の規定による特定健康診査及び特定保健指導を行うものとされている。",a:true,e:"150条1項のとおり。保険者は特定健診等のほか、健康教育・健康相談等の保健事業を行うよう努める。",topic:"保健事業"},
 {id:"X5-272",s:5,q:"全国健康保険協会は、事業年度ごとに財務諸表を作成し、厚生労働大臣の承認を受けなければならないが、事業年度は毎年1月1日に始まり12月31日に終わる。",a:false,e:"協会の事業年度は毎年4月1日に始まり翌年3月31日に終わる。財務諸表は事業年度終了後に作成し厚生労働大臣の承認を受ける。暦年ではない。",topic:"保険者"},
 {id:"X5-273",s:5,q:"適用事業所の任意適用取消しの認可があったときは、その事業所の被保険者は認可のあった日に資格を喪失する。",a:false,e:"任意適用取消しの認可があったときは、その翌日に資格を喪失する(36条)。認可日当日ではない。",topic:"資格喪失"},
 {id:"X5-274",s:5,q:"被保険者が適用除外に該当するに至ったときは、原則としてその翌日に資格を喪失するが、後期高齢者医療の被保険者となったときはその日に喪失する。",a:true,e:"36条のとおり。一般的な喪失事由は翌日喪失、後期高齢者医療の被保険者等となったときはその日に喪失。",topic:"資格喪失"},
 {id:"X5-275",s:5,q:"被保険者の標準報酬月額は、健康保険では第1級58,000円から第50級1,390,000円までの50等級であり、厚生年金保険と同じ等級区分が用いられている。",a:false,e:"健保は50等級(58,000円〜1,390,000円、40条1項)、厚生年金は32等級で下限・上限が異なる。同じ等級区分ではない。",topic:"標準報酬月額"},
 {id:"X5-276",s:5,q:"一般の被保険者に対する保険給付には、療養の給付のほか、傷病手当金、埋葬料、出産育児一時金、出産手当金などがあり、被扶養者に関しては家族療養費、家族埋葬料、家族出産育児一時金などがある。",a:true,e:"52条のとおり。被扶養者に関する給付(家族給付)はすべて被保険者に対して支給される。",topic:"保険給付の種類"},
 {id:"X5-277",s:5,q:"被扶養者が療養のため就労できなくなった場合、被保険者に対して家族傷病手当金が支給される。",a:false,e:"被扶養者に対する傷病手当金(家族傷病手当金)という給付は存在しない(52条)。家族出産手当金も存在しない。",topic:"傷病手当金"},
 {id:"X5-278",s:5,q:"適用事業所以外の事業所が強制適用事業所の要件を満たすに至ったときは、その事業所に使用される者は、要件を満たした日に被保険者の資格を取得する。",a:true,e:"35条のとおり。適用事業所となった日に、そこに使用される者は資格を取得する。",topic:"資格取得"},
 {id:"X5-279",s:5,q:"65歳以上の被保険者が一般病床に入院した場合にも、食事療養ではなく入院時生活療養費が支給される。",a:false,e:"入院時生活療養費は療養病床に入院する65歳以上の者(特定長期入院被保険者)が対象(85条の2)。一般病床の入院なら入院時食事療養費。",topic:"入院時生活療養費"},
 {id:"X5-280",s:5,q:"被扶養者の認定において、認定対象者が60歳以上である場合の年間収入の基準は150万円未満である。",a:false,e:"60歳以上又は一定の障害者の収入基準は180万円未満(通達)。150万円未満は19歳以上23歳未満の者(配偶者を除く)の基準。",topic:"被扶養者"},
 {id:"XT5-01",s:5,format:"choice",examFmt:true,topic:"保険者・健康保険組合",difficulty:3,q:"健康保険の保険者に関する次の記述のうち、正しいものはどれか。",choices:[{t:"全国健康保険協会は、定款で定めるところにより付加給付を行うことができる。",ok:0,why:"誤り。付加給付は健康保険組合が規約で定めて行う(53条)。協会にはない。"},{t:"全国健康保険協会の理事長、理事及び監事は、いずれも厚生労働大臣が任命する。",ok:0,why:"誤り。大臣が任命するのは理事長と監事で、理事は理事長が任命する(7条の11)。"},{t:"日雇特例被保険者の保険は、全国健康保険協会又は健康保険組合が管掌する。",ok:0,why:"誤り。日雇特例被保険者の保険者は協会のみ(123条)。"},{t:"健康保険組合を単独で設立するには、常時300人以上の被保険者を使用している必要がある。",ok:0,why:"誤り。単独設立は常時700人以上、共同設立は合算して常時3,000人以上(施行令)。"},{t:"健康保険組合が解散したときは、その権利義務は全国健康保険協会が承継する。",ok:1,why:"正しい。26条のとおり。組合会の4分の3以上の議決+大臣認可で解散できる。"}],memoryPoint:"大臣任命は理事長・監事。組合設立は単独700人・共同3,000人。解散組合の権利義務は協会へ。",trap:"理事まで大臣任命とする肢、300人と700人の入替え、協会の付加給付が定番のひっかけ。",e:"大臣任命は理事長・監事。組合設立は単独700人・共同3,000人。解散組合の権利義務は協会へ。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-02",s:5,format:"choice",examFmt:true,topic:"適用事業所",difficulty:2,q:"健康保険の適用事業所に関する次の記述のうち、正しいものはどれか。",choices:[{t:"任意適用事業所の認可を受けても、認可申請に同意しなかった者は被保険者とならない。",ok:0,why:"誤り。認可は事業所単位で効力を生じ、同意しなかった者も被保険者となる(31条)。"},{t:"任意適用の取消しの認可を申請するには、被保険者の2分の1以上の同意が必要である。",ok:0,why:"誤り。取消しは被保険者の4分の3以上の同意が必要(33条)。2分の1は任意適用の申請。"},{t:"常時5人以上の従業員を使用する個人経営の税理士事務所は、強制適用事業所となる。",ok:1,why:"正しい。令和4年10月から法律・会計業務の士業が適用業種に追加された(3条3項1号)。"},{t:"常時5人以上の従業員を使用する個人経営の飲食店は、強制適用事業所となる。",ok:0,why:"誤り。個人経営の飲食サービス業は非適用業種で、人数を問わず強制適用とならない(3条3項1号)。"},{t:"同一の事業主が有する2以上の適用事業所は、届出のみで一の適用事業所とすることができる。",ok:0,why:"誤り。一括適用には厚生労働大臣の承認が必要(34条)。"}],memoryPoint:"個人経営は適用業種+常時5人以上で強制適用(士業は令和4年10月追加)。任意適用は2分の1、取消しは4分の3。",trap:"飲食・旅館・農業などの非適用業種を強制適用とする肢。任意適用の同意割合の入替え。",e:"個人経営は適用業種+常時5人以上で強制適用(士業は令和4年10月追加)。任意適用は2分の1、取消しは4分の3。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-03",s:5,format:"choice",examFmt:true,topic:"適用除外・短時間労働者",difficulty:3,q:"健康保険の被保険者・適用除外に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"臨時的事業の事業所に継続して6月を超えて使用されるべき者は、当初から被保険者となる。",ok:0,why:"正しい。3条1項5号のとおり。"},{t:"後期高齢者医療の被保険者は、健康保険の被保険者とならない。",ok:0,why:"正しい。3条1項7号のとおり。75歳到達日に資格を喪失する。"},{t:"大学の夜間学部の学生は、短時間労働者の学生除外の対象とならない。",ok:0,why:"正しい。学生除外は昼間学生が対象。夜間・通信・定時制・休学中は除外されない。"},{t:"2月以内の期間を定めて使用される者であっても、当初からその期間を超えて使用されることが見込まれるときは、当初から被保険者となる。",ok:0,why:"正しい。令和4年10月改正による(3条1項2号ロ)。"},{t:"特定適用事業所に使用される短時間労働者が被保険者となるには、継続して1年以上使用される見込みが必要である。",ok:1,why:"誤り。1年以上見込みの要件は令和4年10月に撤廃された。"}],memoryPoint:"2月以内・日々1月・季節4月・臨時事業6月。短時間の1年要件は撤廃済み。",trap:"撤廃済みの「1年以上見込み」を現行要件として出す改正ひっかけ。",e:"2月以内・日々1月・季節4月・臨時事業6月。短時間の1年要件は撤廃済み。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-04",s:5,format:"choice",examFmt:true,topic:"被扶養者",difficulty:3,q:"健康保険の被扶養者に関する次の記述のうち、正しいものはどれか。",choices:[{t:"被保険者の叔母は、被保険者と同一の世帯に属し主として被保険者により生計を維持されていれば、被扶養者となり得る。",ok:1,why:"正しい。3親等内の親族は同一世帯+生計維持で被扶養者となる(3条7項2号)。"},{t:"被扶養者の認定に係る年間収入には、遺族年金などの非課税収入は含めない。",ok:0,why:"誤り。非課税の公的年金や雇用保険の給付も年間収入に含める(通達)。"},{t:"被保険者の孫が被扶養者となるには、被保険者と同一の世帯に属していることが必要である。",ok:0,why:"誤り。孫は生計維持関係のみで足りる(3条7項1号)。"},{t:"被保険者の兄弟姉妹が被扶養者となるには、被保険者と同一の世帯に属していることが必要である。",ok:0,why:"誤り。兄弟姉妹は平成28年10月から生計維持のみで足りる(3条7項1号)。"},{t:"別居している認定対象者の年間収入が130万円未満であれば、被保険者からの仕送り額にかかわらず被扶養者となる。",ok:0,why:"誤り。別居の場合は130万円未満かつ仕送り額より少ないことが必要(通達)。"}],memoryPoint:"直系尊属・配偶者・子・孫・兄弟姉妹は生計維持のみ。それ以外の3親等内は同一世帯も必要。",trap:"孫・兄弟姉妹に同一世帯を要求する肢。別居なのに2分の1基準を持ち出す肢。",e:"直系尊属・配偶者・子・孫・兄弟姉妹は生計維持のみ。それ以外の3親等内は同一世帯も必要。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-05",s:5,format:"choice",examFmt:true,topic:"資格の得喪",difficulty:2,q:"被保険者の資格の取得及び喪失に関する次の記述のうち、正しいものはどれか。",choices:[{t:"任意適用取消しの認可があったときは、その認可の日に資格を喪失する。",ok:0,why:"誤り。取消しの認可があった日の翌日に喪失する(36条)。"},{t:"被保険者が75歳に達したときは、その翌日に資格を喪失する。",ok:0,why:"誤り。後期高齢者医療の被保険者となったその日に喪失する(36条)。"},{t:"被保険者が死亡したときは、死亡した日の翌日に資格を喪失する。",ok:1,why:"正しい。36条のとおり。退職の場合も翌日喪失。"},{t:"被保険者の資格の取得及び喪失は、事業主が届出をした日にその効力を生ずる。",ok:0,why:"誤り。保険者等の確認によって効力を生じる(39条1項)。効力発生日は事実発生日に遡る。"},{t:"試用期間を設けて採用された者は、本採用となった日に資格を取得する。",ok:0,why:"誤り。試用期間中も使用関係があり、雇入れ日に資格を取得する(35条・通達)。"}],memoryPoint:"喪失は原則翌日、後期高齢者医療への移行はその日。得喪の効力は確認で生じる。",trap:"「翌日」と「その日」の入替え。届出日に効力が生じるとする肢。",e:"喪失は原則翌日、後期高齢者医療への移行はその日。得喪の効力は確認で生じる。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-06",s:5,format:"choice",examFmt:true,topic:"定時決定・随時改定",difficulty:3,q:"標準報酬月額の定時決定及び随時改定に関する次の記述のうち、正しいものはどれか。",choices:[{t:"固定的賃金が増額したが報酬総額が低下して2等級以上下がった場合、随時改定により標準報酬月額が引き下げられる。",ok:0,why:"誤り。固定的賃金と報酬総額の変動方向が逆の場合は随時改定を行わない(通達)。"},{t:"定時決定では、支払基礎日数が11日未満の月を除いて算定するのが一般の被保険者の原則である。",ok:0,why:"誤り。一般の被保険者は17日未満の月を除く。11日は短時間労働者の基準(41条1項)。"},{t:"10月から随時改定された標準報酬月額は、翌年の8月まで適用される。",ok:1,why:"正しい。7月〜12月の改定は翌年8月まで、1月〜6月の改定はその年の8月まで(43条2項)。"},{t:"6月15日に資格を取得した被保険者も、その年の定時決定の対象となる。",ok:0,why:"誤り。6月1日〜7月1日に資格を取得した者は定時決定の対象外(41条3項)。"},{t:"随時改定は、固定的賃金の変動月から起算して3月目の月から行われる。",ok:0,why:"誤り。継続した3月の報酬で判断し、4月目から改定する(43条1項)。"}],memoryPoint:"定時決定は7月1日現在・4〜6月・17日以上。随時改定は4月目から。7〜12月改定は翌年8月まで。",trap:"3月目と4月目、17日と11日、その年8月と翌年8月の入替え。",e:"定時決定は7月1日現在・4〜6月・17日以上。随時改定は4月目から。7〜12月改定は翌年8月まで。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-07",s:5,format:"choice",examFmt:true,topic:"育児休業等終了時改定・標準賞与額",difficulty:3,q:"育児休業等終了時改定及び標準賞与額に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"育児休業等終了時改定は、従前の標準報酬月額と1等級の差しか生じない場合でも行われる。",ok:0,why:"正しい。2等級以上の差は要件ではない(43条の2)。"},{t:"健康保険には、厚生年金保険のような3歳未満の子の養育期間の標準報酬月額の特例はない。",ok:0,why:"正しい。養育期間の特例は厚生年金保険法26条のみ。"},{t:"育児休業等終了時改定は、3歳未満の子を養育する被保険者の申出により行われる。",ok:0,why:"正しい。43条の2第1項のとおり。事業主を経由して申し出る。"},{t:"標準賞与額の上限573万円は、毎年1月1日から12月31日までの累計額で判断する。",ok:1,why:"誤り。毎年4月1日から翌年3月31日までの年度累計で判断する(45条1項)。"},{t:"標準賞与額は、賞与額の1,000円未満の端数を切り捨てて決定する。",ok:0,why:"正しい。45条1項のとおり。"}],memoryPoint:"育休終了時改定は3歳未満・申出・1等級差でも可。標準賞与額は年度累計573万円。",trap:"年度を暦年にすり替える肢。厚年の養育特例を健保にもあるとする肢。",e:"育休終了時改定は3歳未満・申出・1等級差でも可。標準賞与額は年度累計573万円。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-08",s:5,format:"choice",examFmt:true,topic:"保険料の負担・控除・徴収期間",difficulty:3,q:"健康保険の保険料に関する次の記述のうち、正しいものはどれか。",choices:[{t:"同じ月に資格を取得し喪失した場合、その月の保険料は徴収されない。",ok:0,why:"誤り。同月得喪はその月を1か月として保険料を徴収する。"},{t:"毎月の保険料は、当月末日までに納付しなければならない。",ok:0,why:"誤り。翌月末日までに納付する(164条1項)。"},{t:"事業主は、被保険者の当月分の保険料を当月の報酬から控除することができる。",ok:0,why:"誤り。控除できるのは前月分(167条1項)。資格喪失時は前月分と当月分を控除できる。"},{t:"健康保険組合は、規約で定めるところにより、事業主の保険料負担割合を増加することができる。",ok:1,why:"正しい。162条のとおり。協会にはこの特例はない。"},{t:"任意継続被保険者の保険料は、資格喪失時の事業主が2分の1を負担する。",ok:0,why:"誤り。任意継続被保険者の保険料は全額自己負担(161条1項ただし書)。"}],memoryPoint:"控除は前月分、納付は翌月末日、同月得喪は1か月分、組合は事業主負担を増やせる。",trap:"当月分・当月末日へのすり替え。同月得喪をゼロとする肢。",e:"控除は前月分、納付は翌月末日、同月得喪は1か月分、組合は事業主負担を増やせる。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-09",s:5,format:"choice",examFmt:true,topic:"保険料の免除",difficulty:3,q:"保険料の免除等に関する次の記述のうち、正しいものはどれか。",choices:[{t:"育児休業等を月の途中で開始しその月の途中で終了した場合、その月の保険料が免除されることはない。",ok:0,why:"誤り。同月内に14日以上育児休業等を取得すれば当該月の保険料は免除される(159条、令和4年10月改正)。"},{t:"産前産後休業期間中の保険料は、被保険者負担分のみが免除され、事業主負担分は免除されない。",ok:0,why:"誤り。事業主の申出により被保険者分・事業主分とも免除(159条の3)。"},{t:"賞与月の末日に育児休業等をしていれば、休業期間が1週間でも賞与に係る保険料は免除される。",ok:0,why:"誤り。賞与に係る保険料の免除は連続して1月を超える育児休業等の場合に限る(159条)。"},{t:"任意継続被保険者も、育児休業等をしている期間は保険料が免除される。",ok:0,why:"誤り。任意継続被保険者は事業所に使用されておらず、育休免除の対象外。"},{t:"被保険者が刑事施設に拘禁され保険給付が行われない期間であっても、被扶養者がいる場合は保険料が徴収される。",ok:1,why:"正しい。被扶養者には家族給付が行われるため、保険料の不徴収(158条)は被扶養者がいない場合に限る。"}],memoryPoint:"育休免除は月末在籍 or 同月14日以上、賞与は1月超の育休に限る。拘禁中の不徴収は被扶養者がいない場合のみ。",trap:"令和4年10月改正後の14日ルール・1月超ルールを逆に問う肢。",e:"育休免除は月末在籍 or 同月14日以上、賞与は1月超の育休に限る。拘禁中の不徴収は被扶養者がいない場合のみ。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-10",s:5,format:"choice",examFmt:true,topic:"療養の給付・一部負担金",difficulty:2,q:"療養の給付及び一部負担金に関する次の記述のうち、正しいものはどれか。",choices:[{t:"70歳以上の現役並み所得者の判定基準は、標準報酬月額38万円以上である。",ok:0,why:"誤り。標準報酬月額28万円以上(施行令)。"},{t:"70歳以上の被保険者の一部負担金の割合は、70歳に達する日の属する月の翌月以後の療養から原則2割となる。",ok:1,why:"正しい。74条1項2号のとおり。現役並み所得者は3割。"},{t:"保険医療機関の指定は、指定の日から起算して3年を経過したときは効力を失う。",ok:0,why:"誤り。6年で効力を失う(68条1項)。"},{t:"入院中の食事の提供は、療養の給付に含まれる。",ok:0,why:"誤り。食事療養は療養の給付から除かれ、入院時食事療養費の対象(63条2項)。"},{t:"義務教育就学前の被扶養者の家族療養費の給付割合は100分の90である。",ok:0,why:"誤り。100分の80(自己負担2割)(110条2項)。"}],memoryPoint:"70歳到達月の翌月から2割、現役並みは標報28万円以上。就学前は8割給付。指定は6年。",trap:"28万と38万、8割と9割、6年と3年の数字の入替え。",e:"70歳到達月の翌月から2割、現役並みは標報28万円以上。就学前は8割給付。指定は6年。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-11",s:5,format:"choice",examFmt:true,topic:"保険外併用療養費・入院時生活療養費",difficulty:3,q:"保険外併用療養費等に関する次の記述のうち、正しいものはどれか。",choices:[{t:"患者申出療養は、保険医療機関の申出を起点とする。",ok:0,why:"誤り。患者本人の申出を起点とし、臨床研究中核病院の意見書を添える(63条4項)。"},{t:"差額ベッドの提供は評価療養に該当する。",ok:0,why:"誤り。特別の療養環境の提供は選定療養(63条2項5号)。"},{t:"先進医療は選定療養に該当する。",ok:0,why:"誤り。先進医療・治験は評価療養(63条2項3号)。"},{t:"入院時生活療養費は、療養病床に入院する70歳以上の被保険者が対象である。",ok:0,why:"誤り。65歳以上の者が対象(85条の2)。"},{t:"病床数200以上の病院を紹介状なしで初診した場合は、選定療養に該当する。",ok:1,why:"正しい。選定療養の一つ。180日超入院、予約診療、時間外診療も選定療養。"}],memoryPoint:"評価療養=先進医療・治験、選定療養=差額ベッド・200床以上紹介状なし初診・180日超入院。生活療養は65歳以上。",trap:"評価と選定の入替え。生活療養の65歳を70歳にする肢。",e:"評価療養=先進医療・治験、選定療養=差額ベッド・200床以上紹介状なし初診・180日超入院。生活療養は65歳以上。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-12",s:5,format:"choice",examFmt:true,topic:"療養費・訪問看護療養費・移送費",difficulty:3,q:"療養費、訪問看護療養費及び移送費に関する次の記述のうち、正しいものはどれか。",choices:[{t:"指定訪問看護事業者の指定は、都道府県知事が行う。",ok:0,why:"誤り。厚生労働大臣が指定する(88条)。"},{t:"被保険者が自らの判断で保険医療機関以外の病院で受診した場合でも、療養費は常に支給される。",ok:0,why:"誤り。保険者がやむを得ないと認める場合等に限られる(87条1項)。"},{t:"柔道整復師による捻挫の施術は、医師の同意がなくても療養費の対象となり得る。",ok:1,why:"正しい。医師の同意が必要なのは骨折・脱臼の施術(応急手当を除く)(通達)。"},{t:"指定訪問看護を受けたときの基本利用料の割合は、一律1割である。",ok:0,why:"誤り。一部負担金と同じ割合(3割・2割等)(88条)。"},{t:"移送費は、実際に要した費用の全額が支給される。",ok:0,why:"誤り。最も経済的な通常の経路・方法で算定した額で、実費を超えない(97条)。"}],memoryPoint:"療養費はやむを得ない場合。柔整は骨折・脱臼だけ医師同意。訪問看護の指定は大臣、基本利用料は一部負担金と同率。",trap:"介護保険(知事指定)との混同、移送費の実費全額。",e:"療養費はやむを得ない場合。柔整は骨折・脱臼だけ医師同意。訪問看護の指定は大臣、基本利用料は一部負担金と同率。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-13",s:5,format:"choice",examFmt:true,topic:"高額療養費・高額介護合算療養費",difficulty:3,q:"高額療養費等に関する次の記述のうち、正しいものはどれか。",choices:[{t:"同一医療機関の入院と外来の自己負担額は、同じ月であれば合わせて一つとして算定する。",ok:0,why:"誤り。入院と外来、医科と歯科は別々に算定する(通達)。"},{t:"入院時の食事療養標準負担額は、高額療養費の算定対象となる自己負担額に含まれる。",ok:0,why:"誤り。食事・生活療養の標準負担額や差額ベッド代は含まれない。"},{t:"高額介護合算療養費の計算期間は、毎年8月1日から翌年7月31日までである。",ok:1,why:"正しい。医療と介護の両方に自己負担がある世帯が対象(115条の2)。"},{t:"別々の保険者の被保険者である夫婦の自己負担額は、同一世帯であれば合算できる。",ok:0,why:"誤り。世帯合算は同一保険者の被保険者と被扶養者の間で行う。"},{t:"70歳以上の者も、21,000円以上の自己負担額のみを合算の対象とする。",ok:0,why:"誤り。70歳以上は金額を問わずすべて合算できる。21,000円基準は70歳未満。"}],memoryPoint:"高額療養費は暦月・入院外来別・同一保険者で世帯合算。高額介護合算は8月〜翌7月。",trap:"70歳以上にも21,000円基準を当てはめる肢、4月〜3月にすり替える肢。",e:"高額療養費は暦月・入院外来別・同一保険者で世帯合算。高額介護合算は8月〜翌7月。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-14",s:5,format:"choice",examFmt:true,topic:"傷病手当金",difficulty:3,q:"傷病手当金の待期及び他の給付との調整に関する次の記述のうち、正しいものはどれか。",choices:[{t:"待期期間には、年次有給休暇を取得した日は含まれない。",ok:0,why:"誤り。有給休暇の日・公休日も待期に含まれる(通達)。"},{t:"就業時間中に業務外の事由で労務不能となった場合は、その翌日から待期を起算する。",ok:0,why:"誤り。就業時間中に労務不能となった場合はその日から起算する(通達)。"},{t:"在職中の被保険者の傷病手当金は、老齢厚生年金との調整により減額される。",ok:0,why:"誤り。老齢年金との調整は資格喪失後の継続給付を受ける者に限る(108条)。"},{t:"同一の傷病について障害厚生年金を受けられるときは、傷病手当金は一切支給されない。",ok:0,why:"誤り。年金額の360分の1が手当の日額より少なければ差額を支給(108条)。"},{t:"出産手当金を受けられる期間は、傷病手当金の額が出産手当金の額を上回るときに限り、その差額の傷病手当金が支給される。",ok:1,why:"正しい。103条1項のとおり。出産手当金が優先する。"}],memoryPoint:"待期は連続3日(有休・公休含む)。出産手当金優先・差額支給。老齢年金調整は喪失後継続給付のみ。",trap:"就業時間中の起算日、障害厚生年金の全額停止、在職者への老齢年金調整。",e:"待期は連続3日(有休・公休含む)。出産手当金優先・差額支給。老齢年金調整は喪失後継続給付のみ。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-15",s:5,format:"choice",examFmt:true,topic:"出産に関する給付",difficulty:2,q:"出産に関する保険給付について、次の記述のうち正しいものはどれか。",choices:[{t:"妊娠85日以上の人工妊娠中絶は、出産育児一時金の支給対象とならない。",ok:0,why:"誤り。妊娠85日以上であれば人工妊娠中絶も出産に含まれる(通達)。"},{t:"任意継続被保険者が出産したときは、出産育児一時金は支給されるが、出産手当金は支給されない。",ok:1,why:"正しい。出産手当金は任意継続被保険者を除く(102条1項)。"},{t:"双子を出産した場合の出産育児一時金は1児分である。",ok:0,why:"誤り。1児ごとに支給されるため2児分。"},{t:"出産日当日は、出産手当金の支給期間において出産日後の期間に含まれる。",ok:0,why:"誤り。出産日当日は出産日以前(産前)の期間に含まれる。"},{t:"家族出産育児一時金は、被扶養者である配偶者の出産に限って支給される。",ok:0,why:"誤り。被扶養者であれば配偶者に限らない(114条)。"}],memoryPoint:"出産=妊娠85日以上(死産・中絶含む)。一時金は1児ごと。出産日は産前に含む。任継は一時金○・手当金×。",trap:"中絶・死産の除外、出産日を産後に含める肢。",e:"出産=妊娠85日以上(死産・中絶含む)。一時金は1児ごと。出産日は産前に含む。任継は一時金○・手当金×。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-16",s:5,format:"choice",examFmt:true,topic:"埋葬料・資格喪失後の給付",difficulty:3,q:"埋葬料及び資格喪失後の給付に関する次の記述のうち、正しいものはどれか。",choices:[{t:"被保険者が自殺した場合、埋葬料は支給されない。",ok:0,why:"誤り。自殺でも埋葬料は支給される(通達)。"},{t:"資格喪失後の継続給付を受けていた者が、いったん労務可能となった後に再び労務不能となった場合、継続給付が再開される。",ok:0,why:"誤り。いったん労務可能となれば、その後の継続給付は行われない(通達)。"},{t:"被扶養者である妻が死産した場合、死産児について家族埋葬料が支給される。",ok:0,why:"誤り。死産児は被扶養者でないため家族埋葬料は支給されない(通達)。"},{t:"資格喪失後3月以内に死亡した者に係る埋葬料は、継続1年以上の被保険者期間がなければ支給されない。",ok:0,why:"誤り。105条の喪失後3月以内の死亡には1年要件はない。"},{t:"資格喪失後の傷病手当金の継続給付の要件である継続1年以上の被保険者期間には、任意継続被保険者期間を含まない。",ok:1,why:"正しい。104条かっこ書のとおり。"}],memoryPoint:"喪失後の継続給付・出産育児一時金は継続1年(任継期間除く)。喪失後3月以内の死亡は期間要件なし。",trap:"埋葬料にまで1年要件を持ち込む肢、任継期間を1年に算入する肢。",e:"喪失後の継続給付・出産育児一時金は継続1年(任継期間除く)。喪失後3月以内の死亡は期間要件なし。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-17",s:5,format:"choice",examFmt:true,topic:"任意継続被保険者",difficulty:3,q:"任意継続被保険者に関する次の記述のうち、誤っているものはどれか。",choices:[{t:"任意継続被保険者が一般の被保険者となったときは、その日に任意継続被保険者の資格を喪失する。",ok:0,why:"正しい。38条のとおり。翌日ではない。"},{t:"健康保険組合は、規約で定めることにより、任意継続被保険者の標準報酬月額を資格喪失時の標準報酬月額とすることができる。",ok:0,why:"正しい。47条(令和4年1月施行)。"},{t:"保険者は、正当な理由があると認めるときは、資格喪失日から20日を経過した後の申出でも受理することができる。",ok:0,why:"正しい。37条1項ただし書のとおり。"},{t:"任意継続被保険者が資格喪失を申し出たときは、申出が受理された日の属する月の末日の翌日に資格を喪失する。",ok:0,why:"正しい。令和4年1月施行の38条。"},{t:"任意継続被保険者の保険料は、原則としてその月の末日までに納付しなければならない。",ok:1,why:"誤り。その月の10日まで(初月は保険者が指定する日)に納付する(164条1項)。"}],memoryPoint:"任継は2月・20日・2年。保険料は当月10日まで。一般被保険者になったらその日に喪失。申出脱退は受理月末日の翌日。",trap:"納付期日を末日にすり替える肢。喪失日を翌日とする肢。",e:"任継は2月・20日・2年。保険料は当月10日まで。一般被保険者になったらその日に喪失。申出脱退は受理月末日の翌日。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-18",s:5,format:"choice",examFmt:true,topic:"特例退職被保険者・日雇特例被保険者",difficulty:4,q:"特例退職被保険者及び日雇特例被保険者に関する次の記述のうち、正しいものはどれか。",choices:[{t:"特例退職被保険者の制度は、全国健康保険協会も実施することができる。",ok:0,why:"誤り。厚生労働大臣の認可を受けた特定健康保険組合に限られる(附則3条)。"},{t:"日雇特例被保険者の出産育児一時金は、出産日の属する月前2月間に26日分以上の保険料納付が要件である。",ok:0,why:"誤り。出産の月前4月間に26日分以上(137条)。"},{t:"日雇特例被保険者手帳の交付申請は、日雇特例被保険者となった日から起算して10日以内に行う。",ok:0,why:"誤り。5日以内(126条)。"},{t:"日雇特例被保険者の傷病手当金には待期期間がない。",ok:0,why:"誤り。継続した3日間の待期がある(135条)。"},{t:"日雇特例被保険者の療養の給付の支給期間は、同一の傷病について1年間(結核性疾病は5年間)である。",ok:1,why:"正しい。129条のとおり。一般被保険者には期間制限がない点と対比。"}],memoryPoint:"日雇:手帳5日以内、療養1年(結核5年)、傷病手当金6月(指定疾病1年6月)、出産は前4月26日。",trap:"2月26日・6月78日(療養の要件)と4月26日(出産の要件)の混同。",e:"日雇:手帳5日以内、療養1年(結核5年)、傷病手当金6月(指定疾病1年6月)、出産は前4月26日。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-19",s:5,format:"choice",examFmt:true,topic:"給付制限",difficulty:3,q:"保険給付の制限に関する次の記述のうち、正しいものはどれか。",choices:[{t:"療養に関する指示に正当な理由なく従わないときは、保険給付の全部を行わないことができる。",ok:0,why:"誤り。「一部」を行わないことができる(119条)。"},{t:"闘争、泥酔又は著しい不行跡により給付事由を生じさせたときは、保険給付の全部又は一部を行わないことができる。",ok:1,why:"正しい。117条のとおり。"},{t:"被保険者が少年院に収容されている期間は、被扶養者に係る保険給付も行われない。",ok:0,why:"誤り。被扶養者に係る給付は行われる(118条2項)。"},{t:"故意の犯罪行為により給付事由を生じさせたときは、保険給付の全部又は一部を行わないことができる。",ok:0,why:"誤り。故意の犯罪行為・故意の事故は「行わない」(116条)。"},{t:"不正受給による傷病手当金等の支給制限は、偽り等があった日から3年を経過すると行えなくなる。",ok:0,why:"誤り。1年を経過したときは行えない(120条ただし書)。"}],memoryPoint:"故意=行わない、闘争・泥酔=全部又は一部できる、指示違反=一部できる、不正=6月以内(1年経過で不可)。",trap:"「行わない」と「行わないことができる」、「全部」と「一部」の入替え。",e:"故意=行わない、闘争・泥酔=全部又は一部できる、指示違反=一部できる、不正=6月以内(1年経過で不可)。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-20",s:5,format:"choice",examFmt:true,topic:"不服申立て",difficulty:3,q:"健康保険法の不服申立てに関する次の記述のうち、正しいものはどれか。",choices:[{t:"審査請求は、処分があったことを知った日の翌日から起算して6月以内にしなければならない。",ok:0,why:"誤り。3月以内(社会保険審査官及び社会保険審査会法4条)。"},{t:"保険料の徴収処分に不服がある者は、社会保険審査官に審査請求をしなければならない。",ok:0,why:"誤り。保険料等の処分は社会保険審査会への審査請求(190条)。"},{t:"審査請求をした日から3月以内に決定がないときは、審査請求を棄却したものとみなすことができる。",ok:0,why:"誤り。2月以内に決定がないとき(189条2項)。"},{t:"審査請求は、時効の完成猶予及び更新に関しては裁判上の請求とみなされる。",ok:1,why:"正しい。189条3項のとおり。"},{t:"保険給付に関する処分の取消しの訴えは、社会保険審査会の裁決を経た後でなければ提起できない。",ok:0,why:"誤り。社会保険審査官の決定を経た後であれば提起できる(192条)。"}],memoryPoint:"資格・標報・給付=審査官→審査会、保険料=審査会。請求は3月以内、2月で棄却みなし、訴訟は審査官決定後。",trap:"保険料の不服先、2月と3月、訴訟の前置段階の入替え。",e:"資格・標報・給付=審査官→審査会、保険料=審査会。請求は3月以内、2月で棄却みなし、訴訟は審査官決定後。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-21",s:5,format:"choice",examFmt:true,topic:"時効",difficulty:3,q:"時効の起算日に関する次の記述のうち、正しいものはどれか。",choices:[{t:"傷病手当金を受ける権利の時効は、労務不能であった日ごとにその翌日から起算する。",ok:1,why:"正しい。日ごとに権利が発生するため、各日の翌日から2年(193条・通達)。"},{t:"埋葬料を受ける権利の時効は、埋葬を行った日の翌日から起算する。",ok:0,why:"誤り。死亡日の翌日から起算する。埋葬費は埋葬を行った日の翌日。"},{t:"保険料等の納入の告知には時効の更新の効力はない。",ok:0,why:"誤り。納入の告知・督促は時効の更新の効力を有する(193条2項)。"},{t:"療養費を受ける権利の時効は、療養を受けた日の翌日から起算する。",ok:0,why:"誤り。費用を支払った日の翌日から起算する(通達)。"},{t:"保険給付を受ける権利は、行使することができる時から5年で時効消滅する。",ok:0,why:"誤り。2年(193条1項)。"}],memoryPoint:"時効は2年。療養費=支払日の翌日、埋葬料=死亡日の翌日、埋葬費=埋葬日の翌日、傷病手当金=各日の翌日。",trap:"埋葬料と埋葬費の起算日の入替え、年金の5年との混同。",e:"時効は2年。療養費=支払日の翌日、埋葬料=死亡日の翌日、埋葬費=埋葬日の翌日、傷病手当金=各日の翌日。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XT5-22",s:5,format:"choice",examFmt:true,topic:"改正論点(資格確認・被扶養者)",difficulty:3,q:"近年の改正に関する次の記述のうち、正しいものはどれか(2026年4月時点)。",choices:[{t:"被保険者証は2024年12月2日以降も従来どおり新規に発行されている。",ok:0,why:"誤り。令和6年12月2日から被保険者証の新規発行は行われず、電子資格確認が基本となった。"},{t:"被扶養者の認定において、19歳以上23歳未満の者(配偶者を除く)の収入基準は180万円未満である。",ok:0,why:"誤り。令和7年10月から150万円未満。180万円は60歳以上・障害者の基準。"},{t:"出産育児一時金の額は、産科医療補償制度に加入する医療機関での出産の場合、原則42万円である。",ok:0,why:"誤り。令和5年4月から50万円。"},{t:"短時間労働者の適用に係る特定適用事業所の規模要件は、常時100人超とされている。",ok:0,why:"誤り。令和6年10月から常時50人超(51人以上)。"},{t:"マイナンバーカードによる電子資格確認を受けられない者には、保険者から資格確認書が交付される。",ok:1,why:"正しい。被保険者証の廃止に伴う措置(令和6年12月2日施行)。"}],memoryPoint:"被保険者証は令和6年12月2日で新規発行終了→資格確認書。19〜23歳は150万円(令和7年10月)。規模要件51人以上。一時金50万円。",trap:"改正前の数字(100人超・42万円)や別区分の基準(180万円)を混ぜる肢。",e:"被保険者証は令和6年12月2日で新規発行終了→資格確認書。19〜23歳は150万円(令和7年10月)。規模要件51人以上。一時金50万円。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS5-1",s:5,format:"sentaku",sentaku:true,topic:"目的・保険者・健康保険組合",difficulty:3,q:"【選択式】目的と保険者 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"この法律は、労働者又はその被扶養者の[[A]]以外の疾病、負傷若しくは死亡又は出産に関して保険給付を行い、もって国民の生活の安定と福祉の向上に寄与することを目的とする。健康保険(日雇特例被保険者の保険を除く。)の保険者は、全国健康保険協会及び[[B]]とする。全国健康保険協会に、役員として、理事長1人、理事[[C]]以内及び監事2人を置く。健康保険組合は、適用事業所の事業主、その適用事業所に使用される被保険者及び[[D]]をもって組織する。健康保険組合が解散したときは、その権利義務は[[E]]が承継する。",blanks:[{key:"A",ok:10,why:"健保は業務災害(労災保険法7条1項1号)以外の傷病等を対象とする。業務災害は労災保険の担当。",law:"健康保険法1条"},{key:"B",ok:7,why:"保険者は協会と健康保険組合の2つ。日雇特例被保険者の保険者は協会のみ。",law:"健康保険法4条"},{key:"C",ok:12,why:"協会の役員は理事長1人・理事6人以内・監事2人。理事長と監事は大臣任命、理事は理事長任命。",law:"健康保険法7条の9"},{key:"D",ok:4,why:"組合員は事業主・被保険者・任意継続被保険者。組合員だった者の任継はその組合に加入する。",law:"健康保険法17条"},{key:"E",ok:3,why:"解散した健康保険組合の権利義務は協会が承継する。",law:"健康保険法26条"}],options:["日本年金機構","12人","地方公共団体","全国健康保険協会","任意継続被保険者","市町村","日雇特例被保険者","健康保険組合","共済組合","国民健康保険組合","業務災害","9人","6人","他の健康保険組合","3人","通勤災害","特例退職被保険者","公務災害","厚生労働大臣","被扶養者"],memoryPoint:"業務災害以外が対象。保険者は協会と組合。協会理事は6人以内。組合員に任継を含む。解散組合は協会が承継。",trap:"通勤災害を入れたくなるが条文は業務災害。9人は運営委員会の委員数で理事ではない。",e:"【A】業務災害・【B】健康保険組合・【C】6人・【D】任意継続被保険者・【E】全国健康保険協会。業務災害以外が対象。保険者は協会と組合。協会理事は6人以内。組合員に任継を含む。解散組合は協会が承継。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS5-2",s:5,format:"sentaku",sentaku:true,topic:"適用除外・被扶養者",difficulty:3,q:"【選択式】被保険者と被扶養者の範囲 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"適用事業所に使用される者であっても、日々雇い入れられる者は、[[A]]を超えて引き続き使用されるに至った場合を除き、被保険者とならない。季節的業務に使用される者は、継続して[[B]]を超えて使用されるべき場合を除き、被保険者とならない。被扶養者のうち、被保険者の直系尊属、配偶者(事実婚を含む。)、子、孫及び[[C]]は、主としてその被保険者により生計を維持するものであれば足りる。これら以外の被保険者の[[D]]内の親族は、被保険者と同一の世帯に属し、主としてその被保険者により生計を維持するものでなければならない。また、被扶養者は、原則として日本国内に[[E]]を有するものでなければならない。",blanks:[{key:"A",ok:19,why:"日々雇い入れられる者は1月を超えて引き続き使用されると、その超えた日から被保険者となる。",law:"健康保険法3条1項2号イ"},{key:"B",ok:16,why:"季節的業務は4月超の見込みがあれば当初から被保険者。臨時的事業の事業所は6月。",law:"健康保険法3条1項4号"},{key:"C",ok:11,why:"兄弟姉妹は平成28年10月から生計維持のみで被扶養者となる。",law:"健康保険法3条7項1号"},{key:"D",ok:12,why:"それ以外の3親等内の親族は同一世帯+生計維持が必要。",law:"健康保険法3条7項2号"},{key:"E",ok:6,why:"令和2年4月施行の国内居住要件。留学生等は例外的に国内に生活の基礎があるとされる。",law:"健康保険法3条7項"}],options:["2月","1年","20日","本籍","4親等","甥姪","住所","兄弟姉妹の配偶者","3月","国籍","配偶者の父母","兄弟姉妹","3親等","6親等","勤務先","6月","4月","居所","2親等","1月"],memoryPoint:"日々は1月、2月以内の期間雇用は2月、季節は4月、臨時事業は6月。生計維持のみ=直系尊属・配偶者・子・孫・兄弟姉妹。",trap:"季節4月と臨時事業6月の入替え。兄弟姉妹を同一世帯要件側に置く旧制度の知識。",e:"【A】1月・【B】4月・【C】兄弟姉妹・【D】3親等・【E】住所。日々は1月、2月以内の期間雇用は2月、季節は4月、臨時事業は6月。生計維持のみ=直系尊属・配偶者・子・孫・兄弟姉妹。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS5-3",s:5,format:"sentaku",sentaku:true,topic:"一部負担金・保険外併用療養費",difficulty:3,q:"【選択式】療養の給付と保険外併用療養費 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"保険医療機関等から療養の給付を受ける者は、70歳に達する日の属する月以前である場合、療養の給付に要する費用の額に100分の[[A]]を乗じて得た額を一部負担金として支払わなければならない。70歳に達する日の属する月の翌月以後である場合は原則として100分の20であるが、療養の給付を受ける月の標準報酬月額が[[B]]以上である者(収入額が政令で定める額に満たない者を除く。)は100分の30となる。厚生労働大臣が定める高度の医療技術を用いた療養その他の療養であって、保険給付の対象とすべきものであるか否かについて適正な医療の効率的な提供を図る観点から評価を行うことが必要なものを[[C]]といい、被保険者の選定に係る特別の病室の提供その他の療養を[[D]]という。被保険者がこれらの療養を受けたときは、その療養に要した費用について[[E]]を支給する。",blanks:[{key:"A",ok:15,why:"70歳未満(義務教育就学前を除く)の一部負担金は3割。",law:"健康保険法74条1項1号"},{key:"B",ok:0,why:"70歳以上の現役並み所得者の基準は標準報酬月額28万円以上。収入基準未満なら申請で2割。",law:"健康保険法74条1項3号・施行令"},{key:"C",ok:3,why:"先進医療・治験など、将来の保険導入のための評価を行う療養。",law:"健康保険法63条2項3号"},{key:"D",ok:6,why:"差額ベッド、200床以上病院の紹介状なし初診、180日超入院など被保険者の選定に係る療養。",law:"健康保険法63条2項5号"},{key:"E",ok:9,why:"評価療養・患者申出療養・選定療養を受けたときの基礎的部分の給付。",law:"健康保険法86条"}],options:["28万円","20","家族療養費","評価療養","患者申出療養","先進療養","選定療養","25","特別療養費","保険外併用療養費","入院時生活療養費","53万円","高額療養費","38万円","高度療養","30","指定療養","10","26万円","療養費"],memoryPoint:"70歳未満3割、70歳以上原則2割・標報28万円以上は3割。評価療養=先進医療等、選定療養=差額ベッド等。",trap:"28万円と38万円・53万円(高額療養費の所得区分の数字)の混同。評価療養と患者申出療養の取り違え。",e:"【A】30・【B】28万円・【C】評価療養・【D】選定療養・【E】保険外併用療養費。70歳未満3割、70歳以上原則2割・標報28万円以上は3割。評価療養=先進医療等、選定療養=差額ベッド等。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS5-4",s:5,format:"sentaku",sentaku:true,topic:"出産手当金・継続給付・給付調整",difficulty:3,q:"【選択式】出産手当金と給付の調整 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"被保険者が出産したときは、出産の日(出産の日が出産の予定日後であるときは、出産の予定日)以前[[A]](多胎妊娠の場合においては、98日)から出産の日後56日までの間において労務に服さなかった期間、出産手当金を支給する。出産手当金を支給する場合においては、その期間、傷病手当金は支給しない。ただし、その受けることができる傷病手当金の額が出産手当金の額より多いときは、その[[B]]を支給する。資格喪失の日の前日まで引き続き[[C]]以上被保険者(任意継続被保険者又は共済組合の組合員である被保険者を除く。)であった者であって、その資格を喪失した際に傷病手当金又は出産手当金の支給を受けているものは、継続して同一の保険者からその給付を受けることができる。資格喪失後に傷病手当金の支給を受けるべき者が老齢退職年金給付の支給を受けることができるときは、傷病手当金は[[D]]。また、同一の傷病による障害厚生年金との調整では、障害厚生年金の額を[[E]]で除して得た額が傷病手当金の額より少ないときに、その差額が支給される。",blanks:[{key:"A",ok:7,why:"出産手当金は産前42日(多胎98日)・産後56日。予定日より遅れた期間も支給対象。",law:"健康保険法102条1項"},{key:"B",ok:19,why:"出産手当金が優先し、傷病手当金の方が多ければ差額を支給(平成28年改正)。",law:"健康保険法103条1項"},{key:"C",ok:1,why:"継続給付は継続1年以上の被保険者期間(任継期間を除く)が要件。",law:"健康保険法104条"},{key:"D",ok:5,why:"老齢退職年金との調整は喪失後の継続給付受給者のみ。年金の360分の1が手当額より少なければ差額支給。",law:"健康保険法108条"},{key:"E",ok:17,why:"障害厚生年金(同一支給事由の障害基礎年金を含む)の額を360で除した額と比較する。",law:"健康保険法108条・施行規則"}],options:["35日","1年","180","365","全額支給する","原則として支給しない","6月","42日","全額","3分の2","300","2分の1を支給する","2年","3月","支給期間を短縮する","49日","70日","360","2分の1","差額"],memoryPoint:"産前42日・多胎98日・産後56日。出産手当金優先で差額支給。継続給付は1年。年金調整は360分の1。",trap:"98日・56日と42日の混同。在職中の被保険者にまで老齢年金調整をかける誤解。",e:"【A】42日・【B】差額・【C】1年・【D】原則として支給しない・【E】360。産前42日・多胎98日・産後56日。出産手当金優先で差額支給。継続給付は1年。年金調整は360分の1。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS5-5",s:5,format:"sentaku",sentaku:true,topic:"任意継続・保険料",difficulty:3,q:"【選択式】任意継続被保険者と保険料 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"適用事業所に使用されなくなったため被保険者の資格を喪失した者であって、喪失の日の前日まで継続して2月以上被保険者であったものは、喪失の日から[[A]]以内に保険者に申し出ることにより、任意継続被保険者となることができる。任意継続被保険者に関する保険料は、その月の[[B]]までに納付しなければならない(初めて納付すべき保険料を除く。)。事業主は、被保険者に対して通貨をもって報酬を支払う場合においては、被保険者の負担すべき[[C]]の標準報酬月額に係る保険料に相当する額を当該報酬から控除することができる。毎月の保険料は、[[D]]までに納付しなければならない。育児休業等をしている被保険者に係る保険料は、事業主の申出により徴収されないが、育児休業等を開始した日の属する月と終了日の翌日が属する月が同一である場合でも、その月における育児休業等の日数が[[E]]以上であれば、その月の保険料は徴収されない。",blanks:[{key:"A",ok:9,why:"申出は資格喪失日から20日以内。正当な理由があれば経過後も受理できる。",law:"健康保険法37条1項"},{key:"B",ok:11,why:"任意継続被保険者の保険料はその月の10日まで。未納なら納付期日の翌日に資格喪失。",law:"健康保険法164条1項"},{key:"C",ok:5,why:"報酬から控除できるのは前月分。資格喪失時は前月分と当月分を控除できる。",law:"健康保険法167条1項"},{key:"D",ok:19,why:"毎月の保険料は翌月末日までに納付する。",law:"健康保険法164条1項"},{key:"E",ok:8,why:"令和4年10月改正で、同月内に14日以上の育児休業等を取得した月も免除対象となった。",law:"健康保険法159条1項"}],options:["3日","末日","15日","7日","前々月","前月","翌月","翌々月末日","14日","20日","30日","10日","2月","21日","翌月10日","1月","当月","当月末日","5日","翌月末日"],memoryPoint:"任継は2月・20日・2年、保険料は当月10日まで。控除は前月分、納付は翌月末日。育休免除は同月14日以上でも可。",trap:"任継の10日と一般の翌月末日の混同。14日を1月超(賞与免除の要件)と取り違える。",e:"【A】20日・【B】10日・【C】前月・【D】翌月末日・【E】14日。任継は2月・20日・2年、保険料は当月10日まで。控除は前月分、納付は翌月末日。育休免除は同月14日以上でも可。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026},
 {id:"XS5-6",s:5,format:"sentaku",sentaku:true,topic:"不服申立て・時効・給付制限",difficulty:3,q:"【選択式】不服申立てと時効 ─ 本文の空欄A〜Eに入る語句を、下の選択肢から選べ。",passage:"被保険者の資格、標準報酬又は保険給付に関する処分に不服がある者は、[[A]]に対して審査請求をし、その決定に不服がある者は、社会保険審査会に対して再審査請求をすることができる。審査請求をした日から[[B]]以内に決定がないときは、審査請求人は、審査請求が棄却されたものとみなすことができる。保険料等の賦課若しくは徴収の処分又は滞納処分に不服がある者は、[[C]]に対して審査請求をすることができる。保険料等を徴収し、又はその還付を受ける権利及び保険給付を受ける権利は、これらを行使することができる時から[[D]]を経過したときは、時効によって消滅する。被保険者又は被保険者であった者が、自己の故意の犯罪行為により、又は故意に給付事由を生じさせたときは、当該給付事由についての保険給付は、[[E]]。",blanks:[{key:"A",ok:4,why:"資格・標準報酬・保険給付の処分は審査官→審査会の二審制。",law:"健康保険法189条1項"},{key:"B",ok:12,why:"2月以内に決定がなければ棄却みなしで次の段階へ進める。",law:"健康保険法189条2項"},{key:"C",ok:17,why:"保険料等の処分は社会保険審査会への一審制。",law:"健康保険法190条"},{key:"D",ok:15,why:"保険料等の徴収・還付の権利、保険給付を受ける権利はいずれも2年。",law:"健康保険法193条1項"},{key:"E",ok:3,why:"故意の犯罪行為・故意の事故は絶対的給付制限。闘争・泥酔等は「全部又は一部を行わないことができる」。",law:"健康保険法116条"}],options:["3月","行わないことができる","労働保険審査官","行わない","社会保険審査官","1月","その全部又は一部を行わないことができる","労働保険審査会","10年","3年","5年","地方厚生局長","2月","60日","減額して行う","2年","全国健康保険協会","社会保険審査会","厚生労働大臣","その一部を行わないことができる"],memoryPoint:"給付等=審査官→審査会、保険料=審査会。2月で棄却みなし。時効2年。故意は「行わない」。",trap:"保険料の不服先を審査官とする誤り。3月(審査請求期間)と2月(棄却みなし)の混同。故意と闘争泥酔の効果の混同。",e:"【A】社会保険審査官・【B】2月・【C】社会保険審査会・【D】2年・【E】行わない。給付等=審査官→審査会、保険料=審査会。2月で棄却みなし。時効2年。故意は「行わない」。",source:"健康保険法",lawAsOf:"2026-04-01",examYear:2026}
);
